quests[5509] = { id = 5509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings" }
quests[5510] = { id = 5510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Dieners" }
quests[5511] = { id = 5511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zur Scholomance" }
quests[5513] = { id = 5513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, {name}. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", sourceObjective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", sourceObjectiveStatus = "unverified-source-field" }
quests[5514] = { id = 5514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sold reimt sich auf...", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goldstahl. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Apotheker, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", sourceObjective = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goldstahl in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[5515] = { id = 5515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinovs Tasche der Schrecken", description = "Ein großes Gewicht wurde von unseren Herzen genommen, {name}, aber Eure Aufgabe ist noch nicht vollendet. Krastinovs Meister, Kirtonos, lebt immer noch.\n\nBevor Ihr aber Kirtonos gegenübertretet, müsst Ihr Euch zuerst eine Methode besorgen, mit der Ihr ihn beschwören könnt.\n\nEs heißt, dass Jandice Barov das Blut Unschuldiger von Krastinov zu Kirtonos bringt.\n\nSucht sie in den versunkenen Katakomben der Scholomance und streckt sie nieder. Bringt alle Hinweise zurück, die Ihr findet.", sourceObjective = "Sucht nach Jandice Barov in Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", sourceObjectiveStatus = "unverified-source-field" }
quests[5517] = { id = 5517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Chromatische Mantel der Dämmerung", description = "<Bruder/Schwester> {name} -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", sourceObjective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", sourceObjectiveStatus = "unverified-source-field" }
quests[5518] = { id = 5518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", description = "Wenn Ihr versuchen wollt gegen den König dieser Bruchbude zu kämpfen - und ich denke, dass Ihr genau das vorhabt - dann müsst Ihr erstmal an Hauptmann Krombruch vorbei. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen.\n\nEs stellt sich nur die Frage, wie? Nun, ich bin hier schon eine ganze Weile und ich denke, dass ich Euch einen Ogeranzug anfertigen kann, der ausreicht, um diese Kerle zu täuschen. Das einzige Problem wird seine Stabilität sein - zehn Minuten sind das Maximum. Besorgt mir alles was ich brauche und Ihr bekommt einen Ogeranzug. Ich warte hier solange...", sourceObjective = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Zwingschraub. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5519] = { id = 5519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok" }
quests[5521] = { id = 5521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Chromatische Mantel der Dämmerung", description = "<Bruder/Schwester> {name} -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", sourceObjective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5522] = { id = 5522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leonidas Bartholomäus", description = "Ich habe eine Botschaft von meinem Meister Vectus erhalten. Na ja, die Botschaft war nicht wirklich von Vectus... sie war von jemandem namens Leonidas Bartholomäus. Ich kenne Leonidas nicht, aber er kannte meinen Meister, und niemand kennt meinen Meister, außer er lässt es zu.\n\nLeonidas sagt, dass Vectus die Dracheneier will. Er möchte, dass Ihr sie ihm zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern bringt.\n\nDas tut weh! Warum Ihr? Vertraut Vectus mir nicht? Ach, egal... nehmt einfach die Eier und berichtet Leonidas, dass ich getan habe, was unser Meister befahl.", sourceObjective = "Bringt die gefrorenen Eier zu Leonidas Bartholomäus in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5524] = { id = 5524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Chromatische Mantel der Dämmerung", description = "<Bruder/Schwester> {name} -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", sourceObjective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5525] = { id = 5525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit Knot!" }
quests[5526] = { id = 5526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Splitter der Teufelsranke", description = "Euer Wissen über Eldre'Thalas – Düsterbruch – in Feralas wird nun gebraucht, {name}. Im Ostteil der zerstörten Stadt erstreckt sich das Herrschaftsgebiet von Alzzin dem Wildformer. Begebt Euch mit der gebotenen Eile und Tapferkeit dorthin.\n\nDie verderbte Frucht des Gedeihens, die Teufelsranke, sollte sich in Alzzins Nähe befinden. Versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen, wenn er fällt. Versiegelt diese in dem Reliquiar und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", sourceObjective = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Reliquiar der Reinheit, um darin den Splitter sicher zu versiegeln, und bringt das versiegelte Reliquiar zu Rabine Saturna in Nachthafen auf der Mondlichtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[5527] = { id = 5527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Reliquiar der Reinheit", description = "Zuerst müssen wir einen Behälter finden, in dem eine sehr stark verderbte Substanz transportiert werden kann, ohne das der Träger Nebenwirkungen davonträgt. Meines Wissens nach, gibt es nur einen Gegenstand der geeignet ist, darin etwas so abscheuliches wie eine Teufelsranke aufzubewahren: ein Reliquiar der Reinheit.\n\nTief in der Einöde von Silithus befinden sich die Überreste des Nachtelfenpostens Südwind. Vor vielen, vielen Jahren gab es dort ein Reliquiar. Wenn wir Erfolg haben wollen, müsst Ihr die Ruinen durchsuchen, in der Hoffnung dort ein Reliquiar der Reinheit zu finden.", sourceObjective = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nachthafen auf der Mondlichtung zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5528] = { id = 5528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gordokgeschmackstest" }
quests[5529] = { id = 5529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte Jungtiere", description = "Die Argentumdämmerung hat kürzlich erfahren, dass die Geißel ihren eigenen verseuchten Drachenschwarm erschafft! Wir müssen sie stoppen - wenn die Geißel eine Großdrachenstreitmacht auf die Beine stellt, wird sie unbehelligt ganz Azeroth verwüsten!\n\nIhre Totenbeschwörer züchten verseuchte Großdrachen in Scholomance, in der Mitte des Darromersees.\n\nBegebt Euch zur Scholomance und tötet so viele Jungtiere wie nur möglich...bevor sie größer werden können!", sourceObjective = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5530] = { id = 5530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halskette der Dämmerung" }
quests[5531] = { id = 5531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betina Moppelzink", description = "Die Eier, die Ihr gebracht habt, sollten in Experimenten der Geißel verwendet werden, um einen verseuchten Drachenschwarm zu erschaffen. Diese gefrorenen schwarzen Dracheneier wären für ihre Studien unersetzlich gewesen und hätten ihren Zeitplan sicherlich beschleunigt.\n\nNun ist es an der Zeit, dass wir ihre Forschung beenden.\n\nBringt die gefrorenen Eier zu Betina Moppelzink da draußen. Sie ist in Wissenschaft und Alchemie sehr bewandert und hat eine Waffe hergestellt, die wir gegen die Geißel einsetzen können. Mit Eurer Hilfe werden wir ihnen einen schweren Schlag versetzen.", sourceObjective = "Bringt die gefrorenen Eier zu Betina Moppelzink.", sourceObjectiveStatus = "unverified-source-field" }
quests[5532] = { id = 5532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der Dämmerung" }
quests[5533] = { id = 5533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomance", description = "Auf der Insel Darrowehr liegt die Scholomance - ein elendes Zentrum der Totenbeschwörung und des Bösen der Geißel. Unser Feind lebt im Inneren und führt unaussprechliche Taten der Verderbtheit an nichts ahnenden Opfern aus... zumindest vermuten wir das. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nAlchemist Arbington weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert bewiesen und nun vertraue ich Euch diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", sourceObjective = "Sprecht mit Alchemist Arbington an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5534] = { id = 5534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kim'jaels 'fehlende' Ausrüstung", description = "Was?! Was?!\n\nDas war nicht gut genug für Euch? Wisst Ihr, wie teuer diese Sprengstoffe sind? Die kosten... ach, egal. Ihr wollt also echtes Geld machen, ja? Na dann... so läuft das im Geschäftsleben: Ihr beweist, dass Ihr ein wertvoller Angestellter seid und dann werdet Ihr entsprechend belohnt, nachdem Ihr schön brav durchgehalten habt.\n\nFalls Ihr also ein \"wertvoller\" Angestellter seid, dann begebt Euch zu den Ruinen von Eldarath und bringt mir irgendeine Rune, nach der diese Blutelfen gesucht haben. Anscheinend befindet sie sich im Besitz der Naga.", sourceObjective = "Sucht in den Ruinen von Eldarath eine beliebige Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jael in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[5535] = { id = 5535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Unruhe", description = "Vor langer Zeit gehörten die Hochgeborenen zu den mächtigsten Schülern des Arkanen, die die Nachtelfen je hervorgebracht hatten. Die Verderbnis, die mit solchen Studien einhergeht, brachte großes Unglück über die Gesellschaft der Nachtelfen und wirkte sich in großem Umfang auf Azeroth aus... wie Ihr sicherlich wisst.\n\nIch habe den Schildwachen versprochen, dass ich die Geister aus ihren sterblichen Banden befreie, wenn ich sie finde. Wenn Ihr dasselbe tun würdet, kann ich Euch sicherlich belohnen.\n\nDie Geister spuken im Schattensangschrein, von hier aus im Nordosten.", sourceObjective = "Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5536] = { id = 5536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Land voller Hass", description = "Die Satyrn, entstellte und böse Aspekte der Nachtelfen, infizieren jetzt die hochheiligen Länder, die einst von Cenarius bereist wurden. Ich kann nicht für die Nachtelfen sprechen, wenn es um die ganzen Gräueltaten geht, die diese dämonischen Kreaturen begangen haben, aber ich habe der Erdenmutter einen Eid geschworen, den Elfen zu helfen, das Land von solch einer Plage zu befreien.\n\nIch bin sicher, dass Ihr Euch beweisen würdet, wenn Ihr mir bei der Reinigung helfen würdet.\n\nNordöstlich von hier könnt Ihr den Haldarrklan finden. Kehrt zu mir zurück, nachdem Ihr Euch gegen ihre Stärke bewiesen habt.", sourceObjective = "Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zum Eschental zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5537] = { id = 5537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skelettfragmente", description = "Um in die Scholomance zu gelangen, benötigt ihr einen Dietrich. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, {name}. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", sourceObjective = "Bringt 15 Skelettfragmente zu Alchemist Arbington an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5538] = { id = 5538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sold reimt sich auf...", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goldstahl. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Alchemist, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", sourceObjective = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goldstahl in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[5541] = { id = 5541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Munition für Schlingerschuss", description = "Hegnar Schlingerschuss verkauft Gewehre an der Straße nach Ambossar. Scharfschützen und Mörsertrupps verbringen viel Zeit damit, in der Nähe seines Geschäfts zu üben, und er braucht ständig neue Munition.\n\nAber... die letzte Munitionskiste, die ich ihm geschickt habe, ist unterwegs verloren gegangen. Mein Kurier sagte, er lagerte nahe des Graufelsbaus, als Wendigos ihn davonjagten... und der Dummkopf hat Schlingerschuss' Munition zurückgelassen!\n\n{name}, könnt Ihr diese Munition beschaffen und zu Schlingerschuss bringen? Er wartet darauf und ihm gehen bestimmt bald die Vorräte aus.", sourceObjective = "Bringt Schlingerschuss' Munition zu Hegnar Schlingerschuss in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[5542] = { id = 5542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenhunde", description = "Wenn Ihr hier bleiben wollt, bitte ich Euch nur, Euren Unterhalt zu verdienen. Wir haben hier viele Plagegeister, denen etwas 'Disziplin' gut tun würde.\n\nIhr könnt mit den Seuchenhunden und den kleinen Seuchenhunden beginnen.\n\nViel kann ich Euch im Gegenzug nicht anbieten, aber ein warmes Mahl und ein wenig Konversation wäre Euch garantiert, wenn Ihr erfolgreich seid.", sourceObjective = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5543] = { id = 5543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgefärbter Himmel", description = "Wehe jenen, die töricht genug sind, in die Pestländer zu wandern. Alle Arten der Verderbtheit bewohnen diese Wälder - von den fanatischen Anhängern des Scharlachroten Kreuzzugs, die jeden töten, der nicht das Zeichen der Kreuzzügler trägt, bis hin zur mordlustigen Geißel, die ihre Anzahl vergrößern will, indem sie ihre Ränge mit Untoten füllt.\n\nSogar die Tierwelt wurde in wilde, menschenfressende Bestien verwandelt. Ich bitte Euch, die zu vernichten, die vom Firmament aus zuschlagen: die Seuchenfledermäuse.", sourceObjective = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5544] = { id = 5544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aassammlung", description = "Meine Essensvorräte gehen zur Neige, {race}. Ich schäme mich zuzugeben, dass ich möglicherweise nicht genug Nahrung habe, um sie mit Euch zu teilen.\n\nKönnt Ihr einem alten Mann bei einer einfachen Aufgabe helfen? Hier in der Umgebung sind Aaswürmer die einzigen Tiere, die von den Verheerungen der Seuche unbeeinflusst blieben. Wenn sie auch ziemlich langweilig schmecken, kann das Fleisch der Würmer doch leicht monatelang aufbewahrt werden. Ich werde einige hundert Pfund benötigen, um meine Vorräte für den kommenden Winter aufzustocken!", sourceObjective = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5545] = { id = 5545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel Probleme", description = "Ich habe hier ein echtes Problem. Ich habe einen Liefertermin für eine Bestellung Holz und mir läuft die Zeit davon. Die Wölfe und Bären nördlich von hier haben meine Arbeiter von den Holzbündeln verjagt, die sie bereits gefällt hatten.\n\nIch habe bereits mit Stellvertreter Rainer darüber gesprochen, dass die Tiere entfernt werden müssen, aber ich brauche jemanden, der das Holz für mich holt. Wenn Ihr acht Holzbündel für mich holen würdet, könnte ich den Termin vielleicht noch einhalten.", sourceObjective = "Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", progress = "Der Termin kommt immer näher, {class}. Beeilt Euch bitte und holt diese Holzbündel.", completion = "Exzellent! Dank Euch sollte ich die Bestellung rechtzeitig zusammenstellen können. Um Euch meine Dankbarkeit zu zeigen, würde ich Euch gern ein paar Münzen als Entschädigung für Eure Mühen anbieten.\n\nVielen Dank und lebt wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[5561] = { id = 5561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodozusammentrieb", description = "Bibbly glaubt, dass er der einzige Goblin in Desolace sei, der weiß, wie man Geld macht. Tja, die einzige Karawane, die mutig genug ist, diese Gebiete zu bereisen, verlässt sich auf mich. Nachdem ich gelernt habe, wie man alternde Kodos mit meinem Kodokombobulator verjüngt und kontrolliert, sind die Karawanenbesitzer Cork und Rigger mit mir eine Partnerschaft eingegangen.\n\nNehmt den Kombobulator und wendet ihn auf jeden beliebigen alten oder alternden Kodo an; er wird das Biest in einen gezähmten Kodo verwandeln und es zwingen, Euch zu folgen. Wenn Ihr einen Kodo gezähmt habt, bringt ihn zu mir her.", sourceObjective = "Bringt 3 gezähmte Kodos sowie den Kodokombobulator zu Smeed Schraubenbuddel bei Schraubenbuddels Lager.", progress = "Die Karawane wird bald hier sein; habt Ihr die frisch gezähmten Kodos, um die ich gebeten hatte?", completion = "<Smeed Schraubenbuddel beginnt zu zählen.>\n\nDrei, hervorragend, ich habe um drei gezähmte Kodos gebeten und ich habe drei gezähmte Kodos bekommen... Ich werde reich sein... ja, sehr reich. Ich würde zu gern den Ausdruck auf Bibblys grünem Gesicht sehen, wenn er von meinem Erfolg hört!", sourceObjectiveStatus = "unverified-source-field" }
quests[5581] = { id = 5581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portale der Legion", description = "Seht - die Hand von Iruxos.\n\nIch habe sie selbst einem der Anführer der Brennenden Klinge abgenommen.\n\nIhr müsst sie besitzen, wenn die Dämonenportale beim Zirkel der Mannoroc gebannt werden sollen... und genau darum bitte ich Euch nun.\n\nDie Bedrohung durch die Dämonen steigt stetig und wir müssen diese Portale schließen, um die Flut der Dämonen, die in diese Welt eindringen, zu stoppen.", sourceObjective = "Verbannt 6 Portale beim Zirkel der Mannoroc und kehrt dann zu Felgur Zweischneid zum Geistwandlerposten zurück.", completion = "Eure Bemühungen haben dabei geholfen, den Feind zu verlangsamen, {class}.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[5582] = { id = 5582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesunde Großdrachenschuppe", description = "Dies ist eine Schuppe von einem verseuchten Großdrachen-Jungtier. Aber im Gegensatz zu den anderen pockennarbigen, eiternden Schuppen an dem kleinen Biest ist diese rare Schuppe gesund und unbeschädigt.\n\nBetina Moppelzink wird eine Probe davon für Forschungen haben wollen.", sourceObjective = "Bringt die gesunde Großdrachenschuppe zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5601] = { id = 5601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwester Pamela", description = "Ich bin während des großen Krieges aus Lordaeron geflohen und hatte das Glück, entkommen zu können, bevor die Geißel durch meine Heimat fegte und sie zu einem verseuchten Alptraum machte! Ich hatte Glück, aber meine Familie nicht. Ich fürchte, dass sie während der Schlacht von Darroheim getötet wurden.\n\nDarroheim ist ein Dorf in den Östlichen Königreichen, eingebettet in die südlichen Hügel dessen, was heutzutage Östliche Pestländer genannt wird. Würdet Ihr Euch dorthin begeben und nach meiner Familie suchen? Ich vermisse sie so sehr, besonders meine kleine Schwester Pamela.\n\nBitte, sucht sie für mich!", sourceObjective = "Sucht Pamela Rotpfad in Darroheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[5621] = { id = 5621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Mondes", description = "Ich brauche Eure Hilfe, {name}. Ich kann hier nicht weg, denn ich muss hier die anderen Schüler unterweisen, doch Ihr könntet einer unserer verwundeten Schildwachen direkt südlich von Dolanaar helfen. Sie wurde beim Patrouillieren der Stadt verletzt und benötigt unsere Hilfe. Ihr Name ist Shaya.\n\nWenn Ihr sie findet, heilt ihre Wunden, und stärkt dann ihren Körper mit Euren Zaubern. Das wird sie zumindest etwas länger vor Schaden bewahren, wenn es wieder hart auf hart kommt. Kehrt zu mir zurück, nachdem Ihr Eure Pflicht gegenüber Elune erfüllt habt.", sourceObjective = "Sucht die Schildwache Shaya und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morgenglanz in Dolanaar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5622] = { id = 5622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune geneigt", description = "{name}, sobald Eure Aufgaben hier im Laubschattental abgeschlossen sind, müsst Ihr nach Dolanaar reisen. Dort werdet Ihr Laurna Morgenglanz finden. Sie wird Euch weiter in den Dingen Elunes unterweisen und bei ihr werdet Ihr Euch Eure ersten Gewänder verdienen, die Eure Position als <Priester/Priesterin> von Elune kennzeichnen.\n\nSeid vorsichtig und möget Ihr auf Euren Reisen beschützt werden.", sourceObjective = "Sprecht mit Laurna Morgenglanz in Teldrassil.", sourceObjectiveStatus = "unverified-source-field" }
quests[5623] = { id = 5623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Licht geneigt", description = "Ich grüße Euch, <junger Priester/junge Priesterin>. Die Zeit ist gekommen, mehr über unsere Religion zu lernen. Nachdem Ihr Eure Aufgaben hier in Nordhain abgeschlossen habt, sucht bitte Priesterin Josetta in Goldhain auf. Sie kann Euch noch mehr beibringen und hat gehört, dass Ihr in den Wegen des Lichts gut voranschreitet. Sie freut sich darauf, Euch weiter unterrichten zu können.", sourceObjective = "Sprecht mit der Priesterin Josetta im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[5624] = { id = 5624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Lichts", description = "Normalerweise stelle ich den Gefolgsleuten des Lichts eine kleine Herausforderung, um ihre Fertigkeiten zu prüfen. Ich möchte sehen, ob sie es wert sind, ihre ersten Roben zu tragen - sie sind ein Zeichen, dass die Kirche <den Priester/die Priesterin> nach außen hin trägt und unterstützt.\n\nDoch hier ist die Situation etwas anders. Einer der Bürger von Goldhain sah eine verletzte Wache nahe dem See östlich von hier. Er heißt Roberts. Sucht ihn, heilt ihn, stärkt seinen Körper und kehrt hierher zurück. Wenn Ihr das für mich tun könnt, dann werde ich Eure Prüfung als bestanden ansehen.", sourceObjective = "Sucht die Wache Roberts und heilt seine Wunden mithilfe von 'Blitzheilung'.", sourceObjectiveStatus = "unverified-source-field" }
quests[5625] = { id = 5625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Lichts", description = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen. Doch um ehrlich zu sein, gibt es wichtigere Dinge, um die ich mich kümmern muss. Bürger von Kharanos kamen gerade hierher und erzählten mir von einem verletzten Gebirgsjäger direkt außerhalb der Stadt im Süden - sein Name ist Dolf.\n\nWenn Ihr Dolf heilt und ihm 'Seelenstärke' gebt, werde ich das als erfolgreiche Prüfung ansehen. Wie klingt das?", sourceObjective = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5626] = { id = 5626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Licht geneigt", description = "He! {name}! Habt Ihr einen Moment Zeit?\n\nIhr seid dem Licht jetzt lange genug gefolgt, um den Weg zu Maxan Anvol in Kharanos zu finden. Er wird Euch mehr über den Weg beibringen, dem Ihr folgt, und wenn Ihr Euch als würdig erweist, wird er Euch Eure ersten Roben geben, die Eure Position als <Priester/Priesterin> kennzeichnen.\n\nAlso dann mal los! Sobald Ihr hier fertig seid, geht durch den Tunnel - er wird auf Euch warten.", sourceObjective = "Sprecht mit Maxan Anvol in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[5627] = { id = 5627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterne von Elune" }
quests[5628] = { id = 5628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Ah, ja, hallo, {name}? Ich freue mich, dass Ihr auf ein kurzes Gespräch hereinschaut. Ihr seid weit fort von zu Hause, und das in so jungen Jahren - ich bewundere einen solchen Ehrgeiz. Ich wünschte, ich hätte den Mut gehabt, durch die Welt zu reisen, als ich noch jünger war.\n\nEine Priesterin Eures Ordens war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie sagt, Ihr müsstet dringend in den Tempel des Mondes in Darnassus zurückkehren und mit Priesterin Alathea sprechen - es hatte etwas mit Eurer Ausbildung zu tun. Ich würde nicht zu lange trödeln, wenn es irgendwie geht.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5629] = { id = 5629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Hallo, {name}. Ich weiß, dass Ihr damit beschäftigt wart, unserem Volk zu helfen, aber Ihr müsst Euch auch Zeit für Euch selbst nehmen. Die Priesterin Alathea hat jemanden hergeschickt, um nach Euch zu suchen. Es scheint, dass Ihr die Aufmerksamkeit unserer Ältesten erregt habt, und sie sind der Meinung, dass Ihr für größere Dinge bereit seid. Begebt Euch zum Tempel des Mondes in Darnassus und sucht dort nach Alathea. Sie wird Euch erwarten. Viel Glück, und möge Elune mit Euch sein.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5630] = { id = 5630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Hallo, <Bursche/Mädel>. Es ist gut zu sehen, dass Ihr entfernte Länder weit und breit bereist. Ich will Euch nicht beleidigen, aber viele Eurer Art vertragen das kalte Klima normalerweise nicht gut. Schön zu sehen, dass Ihr aus härterem Holz geschnitzt seid.\n\nVor nicht allzu langer Zeit war eine Eurer Priesterinnen hier und hat nach Euch gesucht - sie sagte so etwas in dem Sinne, dass Ihr eine Priesterin Alathea im Tempel des Mondes in Darnassus aufsuchen solltet. Sagte, es wäre wichtig und Ihr solltet Euch bald dorthin begeben.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5631] = { id = 5631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Eine Priesterin hat kürzlich unsere Hallen besucht und Euch gesucht, {race}. Sie sagte, sie hätte den Auftrag, Euch zu finden, und dass Ihr so bald wie möglich zum Tempel des Mondes in Darnassus zurückkehren solltet. Wenn Ihr ankommt, sucht Priesterin Alathea auf - sie wird Euch mehr berichten.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5632] = { id = 5632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Oh, aber ja, natürlich. Hallo, {name}. Eine Botin von Eurem Orden war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie erwähnte, dass in Darnassus etwas Wichtiges geschieht und dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Wenn Ihr dort ankommt, sprecht mit Priesterin Alathea. Ich glaube, es hat etwas damit zu tun, dass Ihr so gute Fortschritte beim Verständnis unserer Bräuche macht.\n\nWie gesagt, kehrt nach Darnassus zurück, sobald Ihr könnt.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5633] = { id = 5633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Seid gegrüßt, <Bursche/Mädel>. Es ist schön, Euch hier in unseren großen Hallen zu sehen. Ein Segen sei mit Euch und Eurer Art.\n\nWährend Ihr durch unsere Länder gereist seid, kam eine Priesterin Eures Tempels her, die nach Euch suchte. Sie sagte, dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Es tut mir leid, dass ich Euch nicht mehr berichten kann, aber es klang wichtig. Wenn Ihr zum Tempel kommt, sprecht mit Priesterin Alathea.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5634] = { id = 5634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet" }
quests[5635] = { id = 5635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Ihr habt die Aufmerksamkeit unserer Vorgesetzten erregt, {name}. Sie bitten, dass Ihr so bald wie möglich zur Kathedrale des Lichts in Sturmwind reist. Anscheinend sind sie der Meinung, dass Ihr Euch bereits würdig erwiesen habt und bereit seid, Eure Ausbildung weiterzuführen. Wenn Ihr dort anlangt, sucht nach der Hohepriesterin Laurena. Sie kann Euch weitere Anweisungen geben. Viel Glück, und möge das Licht mit Euch sein.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5636] = { id = 5636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Elune segne Euch, {race}. Ich hoffe, dass Euer Licht Euch findet und Euch heute gut schützt.\n\nEiner Eurer Priester war vor nicht allzu langer Zeit hier und suchte nach Euch. Er erwähnte, dass Ihr sobald wie möglich zur Kathedrale des Lichts zurückkehren und mit der Hohepriesterin Laurena sprechen sollt. Es scheint, als hättet Ihr Euch wacker geschlagen, dass Ihr eine solche Aufmerksamkeit erlangt. Ich würde hier nicht allzu viel Zeit verbringen - Eure Leute brauchen Euch.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5637] = { id = 5637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Die Zeit ist für Euch gekommen, nach Sturmwind zu gehen, {name}. Die Hohepriesterin Laurena in der Kathedrale des Lichts möchte mit Euch sprechen. Es muss etwas sehr Gutes oder sehr Schlechtes sein, wenn die Hohepriesterin Euch persönlich dort sehen will, aber ich denke, dass Ihr selbst nur Gutes getan habt und dass es eine gute Sache ist, dass sie mit Euch sprechen möchte.\n\nVerschwendet hier aber nicht allzu viel Zeit. Ich an Eurer Stelle würde mich umgehend auf den Weg machen.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5638] = { id = 5638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Vor kurzer Zeit kam einer Eurer Priester her und suchte nach Euch, {race}. Er sagte, dass ich Euch zur Kathedrale des Lichts schicken solle, wenn ich Euch sehen würde. Er sagte, es sei sehr wichtig, aber ich an Eurer Stelle würde mir trotzdem nicht allzu viele Sorgen machen. Seine Haltung erschien positiv...als ob es gute Neuigkeiten wären. Auf jeden Fall solltet Ihr Euch beeilen, wenn Ihr meine Meinung wissen wollt.\n\nElune sei mit Euch, {race}.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5639] = { id = 5639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Ihr werdet in Sturmwind gebraucht, {name}! Die Hohepriesterin dort, Laurena, sagt, es sei an der Zeit für Euch zu beweisen, dass Ihr der nächsten Stufe Eurer Ausbildung würdig seid. Verschwendet nicht zu viel Zeit auf dem Weg dorthin. Ihr könnt sie in der Kathedrale des Lichts im Zentrum der Stadt finden. Überbringt Ihr meine Wünsche und beweist, wie würdig Ihr eines solchen Rufes seid. Das Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5640] = { id = 5640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Gepriesen seien Elune und Euer Licht, {name}.\n\nZurzeit erlernen viele unseres Ordens Fähigkeiten, die ihren Glauben an Elune widerspiegeln. Wenn ich mich nicht irre, gilt das Gleiche auch für Euren Orden.\n\nWenn Eure Angelegenheiten in Darnassus abgeschlossen sind, solltet Ihr eine Eurer Hohepriesterinnen zur weiteren Ausbildung aufsuchen.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5641] = { id = 5641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtlos" }
quests[5642] = { id = 5642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwache", description = "In Orgrimmar geht etwas Wichtiges vor, {name}.\n\nNormalerweise sind die Boten, die hier durchkommen und nach Trollpriestern suchen, recht umgänglich. Dieses Mal schienen sie jedoch in großer Eile zu sein. Trödelt nicht zu lange in Donnerfels herum. Ich würde so schnell wie möglich zum Tal der Geister zurückkehren.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5643] = { id = 5643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwache", description = "Wie viele unserer eigenen Priester werdet Ihr von Eurem Stamm durch die Initiationsriten geführt. Diese Riten lehren Priester häufig besondere Fähigkeiten, die wichtig für ihr Überleben sind. Ich spüre, dass die Zeit jetzt an Euch ist, jetzt, in diesem Augenblick. Ihr müsst zum Tal der Geister in Orgrimmar zurückkehren und mit Ur'kyo sprechen. Was er Euch lehrt, kann für die Zukunft sehr wichtig sein.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5644] = { id = 5644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingende Seuche", description = "Ah, ein wundervoller Tag für Euch, {name}. Aufgrund der Lektionen, die Ihr gelernt habt, kann ich sehen, dass die Zeit gekommen ist, Euch zu Aelthalyste zurückzuschicken. Es gibt Dinge, die nur sie Euch beibringen kann, und auch das nur, wenn Ihr Euch als würdig erweist.\n\nIch werde die Überraschung für Euch nicht verderben, aber ich erinnere mich daran, wie es war, als ich ein junger Priester war und etwas über die wahre Macht lernte...die göttliche Macht. Ja, das waren noch Zeiten.\n\nKehrt zu Aelthalyste nach Unterstadt zurück, {name}. Sie erwartet Euch im Kriegsviertel.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5645] = { id = 5645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtlos", description = "{name}, Euer Hohepriester Rohan erwartet Euch zu einer Audienz in Eisenschmiede. Beeilt Euch, Eure nächste Prüfung rückt schnell näher. Auch wenn ich wünschte, dass ich Zeuge der besonderen Riten Eures Volkes sein könnte, ist mein Platz doch hier. Aber möge das Licht während Eurer Reisen mit Euch sein. Rohan sollte sich noch im Mystikerviertel befinden, wenn Ihr die Stadt erreicht. Er wird Euch erwarten.", sourceObjective = "Sprecht mit Hohepriester Rohan in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[5646] = { id = 5646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingende Seuche", description = "Aelthalyste bezeugt unserem Volk großen Respekt, indem sie unsere Leute zur weiteren Ausbildung zu mir schickt, und nun tue ich dasselbe für ihren Stamm.\n\nKehrt nach Unterstadt zurück, {name}. Dort, im Kriegsviertel, wartet sie auf Euch und ist bereit, Euch mehr über Euer Volk und seine Wege zu lehren. Begebt Euch dorthin und zögert nicht lange.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5647] = { id = 5647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtlos", description = "Euer Volk ist sehr stark, {name}. Wir sind stolz darauf, Euch Verbündete nennen zu können. Mit jedem Sonnenuntergang nähert Ihr und Eure Art Euch nicht nur Euren wahren Wurzeln, sondern seid auch immer sicherer, dass Ihr in sehr vielen Belangen auf dem richtigen Weg seid. Das muss Euch ein so wunderbares Gefühl geben.\n\nErst vor Kurzem erhielten wir eine Nachricht aus Eisenschmiede. Sie besagte, dass Ihr dorthin zurückkehren und mit dem Hohepriester Rohan im Mystikerviertel sprechen sollt. Ich würde ihn nicht warten lassen. Möge Elune Eure Reisen leiten.", sourceObjective = "Sprecht mit Hohepriester Rohan in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[5648] = { id = 5648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder der Spiritualität", description = "Ihr seid bereit für Eure erste Prüfung, {name}. Südlich von Klingenhügel, direkt vor der Stadt, wurde eine Grunzerin verletzt, als sie einige von Prachtmeers alten Truppen bekämpfte. Es geht ihr nicht allzu gut und es wäre wirklich gut, wenn einer unserer Art ihr helfen könnte. Sucht sie - ihr Name ist Kor'ja -, heilt ihre Wunden und gebt ihr den Segen unserer Vorfahren.\n\nWenn Ihr das tut, sehe ich das als ausreichenden Beweis dafür an, dass Ihr bereit seid, unseren Pfad weiter zu beschreiten.", sourceObjective = "Findet die Grunzerin Kor'ja und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5649] = { id = 5649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spiritualität geneigt", description = "Ja, Mann. Unser Volk hat sich der Horde angeschlossen, weil sie gut für uns ist. Die da sind loyal und lehren uns viel über Dinge wie Ehre. Aber unsere alten Gewohnheiten sterben nur langsam. Die Orcs mögen nicht alle unsere Traditionen billigen, aber das bedeutet nicht, dass wir einige davon nicht im Geheimen ausüben können.\n\nIhr wisst das, und darum schicke ich Euch zu Tai'jin in Klingenhügel. Sie wird Euch mehr über unsere Geschichte lehren. Sie wird Euch in den Wegen unseres Stammes unterrichten. Geht zu ihr, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Tai'jin in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5650] = { id = 5650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder der Dunkelheit", description = "Unsere Macht beziehen wir aus der Dunkelheit und dem Schatten, {name}, doch das ist nicht Eure einzige Rolle. Ihr habt erkannt, dass es von Vorteil ist, sich in der Heilkunst auszukennen. Das ist weise. Doch bevor Ihr die Dunkelheit kennen lernen könnt, müsst Ihr erst das Licht kennen. Und daher habe ich eine Prüfung für Euch.\n\nNördlich des Friedhofs befindet sich eine verwundete Todeswache - Todeswache Kel. Er hat uns seit geraumer Zeit vor Gnollen beschützt und braucht Heilung. Doch Ihr müsst auch seinen Körper stärken, bevor er seinen Dienst wieder aufnehmen kann. Tut beides mit Euren Zaubern und kehrt dann zu mir zurück.", sourceObjective = "Findet die Todeswache Kel und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryll in Brill zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5651] = { id = 5651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelheit geneigt", description = "Es gibt viele Lektionen, die die Verlassenen durch Erfahrung gelernt haben... Dinge, die einige Völker allenfalls erahnen können. Und obwohl unser Weg in Dunkelheit liegt, werdet Ihr feststellen, dass sehr viele Dinge sowohl vom Licht als auch von der Dunkelheit abhängen. Eure Lektionen sollen Euch lehren, beides zu nutzen... mit Umsicht. Aber beachtet meine Worte: vergesst nie, wir wurden in die Verderbnis gezwungen und der Fäulnis überlassen wie ein Stück Aas. Die Dunkelheit ist unser Heim.\n\nSucht den Dunklen Kleriker Beryll in Brill auf, wenn Ihr bereit seid, mehr zu erfahren.", sourceObjective = "Sprecht mit dem Dunklen Kleriker Beryll in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5652] = { id = 5652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche" }
quests[5654] = { id = 5654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Es ist an der Zeit, Euch mit Ur'kyo zu treffen, {name}. Er befindet sich im Tal der Geister in der Stadt der Orcs. Geht dorthin und sprecht mit ihm. Es ist an der Zeit, dass Ihr mehr über die alten Wege unserer Art lernt. Es wird Zeit, dass Ihr in den Kreis eingeführt und zu einem wahren Priester unseres Stammes gemacht werdet.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5655] = { id = 5655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Ich wurde hergeschickt, um sicherzustellen, dass Ihr Euch nicht zu sehr von der Heimat entfernt, {name}. Sie haben mich geschickt, um sicherzustellen, dass Ihr nach Hause zurückkehrt, da Ur'kyo, der größte unserer Priester, mit Euch zu sprechen wünscht. Begebt Euch dorthin. Begebt Euch zum Tal der Geister in der Stadt der Orcs und sprecht mit Ur'kyo. Er wartet auf Euch.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5656] = { id = 5656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Es erwärmt immer mein nicht sterbendes Herz, Priester aus allen Kulturen zu sehen, die durch die Welt ziehen. Zu wissen, dass Macht existiert, die nicht arkan und sehr wohl in unserer Reichweite ist. Daher ist es mir eine Ehre, Euch nach Hause zu schicken, {name}.\n\nUr'kyo, Euer großer Priester in Orgrimmar, bittet um Eure Anwesenheit. Ihr findet ihn im Tal der Geister.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5657] = { id = 5657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Nach Hause. Kehrt nach Hause zurück, {race}.\n\nEuer spiritueller Anführer Ur'kyo bittet Euch, zu ihm zurückzukehren und mit ihm über den Weg zu sprechen, den Ihr geht.\n\nBegebt Euch zum Tal der Geister in der großen Hordenstadt Orgrimmar. Dort werde Ihr ihn finden.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5658] = { id = 5658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche" }
quests[5660] = { id = 5660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Ihr seid weit weg von zu Hause, {class}. Ihr werdet dort gebraucht, dort, in Eurer Stadt unter dem Boden. Eure Meisterin, diejenige, die Ihr Aelthalyste nennt, braucht Euch dort. Genau wie bei meinem Stamm gibt es dort Dinge, die Ihr nur von ihr lernen könnt. Bleibt nicht zu lange hier. Ihr solltet Euch zum Kriegsviertel begeben, so schnell ein Zeppelin Euch tragen kann.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5661] = { id = 5661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Ihr seid weit weg von zu Hause, hier im Dorf der Bluthufe, {name}. Ich wurde hierher geschickt, um Priester meines eigenen Stammes zu finden und sie zurückzuschicken, um mit unseren Anführern zu sprechen, aber das bedeutet nicht, dass ich Euch nicht auch helfen kann.\n\nIch habe gehört, dass der Geist Eurer führenden Priesterin möchte, dass alle Verlassenen zu ihr kommen - es gibt Dinge, die Ihr lernen müsst.\n\nTrefft Euch mit Aelthalyste im Kriegsviertel, in Eurer Stadt.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5662] = { id = 5662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Mein Respekt gilt Euch und Eurer Art, {name}. Normalerweise lehre ich nur die meines eigenen Stammes. Eure Lektionen kommen von Aelthalyste in der Stadt, die einst Lordaeron genannt wurde.\n\nIhr solltet zur ihr zurückkehren, wenn Ihr die Fähigkeiten erlernen wollt, die Euch von anderen Glaubensrichtungen abgrenzen.\n\nBegebt Euch ins Kriegsviertel in Unterstadt und sucht dort nach Eurer Meisterin.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5663] = { id = 5663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Aelthalyste schickte eine Nachricht an alle ihre Priester. Wir sollen die Jüngeren unseres Ordens für die weitere Ausbildung nach Unterstadt schicken. Wenn Ihr Euch wahrlich zu unseren Gläubigen zählt, dann solltet Ihr auch dorthin zurückkehren.\n\nIhr könnt Aelthalyste im Kriegsviertel in Unterstadt finden.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5672] = { id = 5672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut" }
quests[5673] = { id = 5673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", description = "Ihr wisst, dass Ihr jederzeit zu jedem unserer Lehrer Zugang habt, {name}, aber es gibt einige Dinge, die wir nicht an Euch weitergeben können. Eines dieser Dinge sind die Lehren der Göttin Elune. Sie verleiht ihren Getreuen spezielle Fähigkeiten, und wenn ich mich nicht irre, ist es an der Zeit, dass Ihr nach Hause zu Eurem Tempel des Mondes zurückkehrt, um geprüft zu werden.\n\nKehrt dorthin zurück, wenn Ihr könnt, und sprecht mit der Priesterin Alathea.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5674] = { id = 5674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", description = "Ein wunderbarer Tag ist gekommen, {name}. Ihr habt das Alter erreicht, in dem unsere <Priester/Priesterinnen> in Fähigkeiten ausgebildet werden, die nur die Nachtelfen kennen. Aber es ist nicht an mir, Euch auszubilden. Ihr müsst zum Tempel des Mondes zurückkehren und mit der Priesterin Alathea sprechen, sobald Ihr Eure Angelegenheiten hier abgeschlossen habt. Sie wird Euch prüfen, um sicher zu sein, dass Ihr bereit seid, und erst dann wird sie Euch Elunes Anmut lehren.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5675] = { id = 5675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", description = "Die Zeit verrinnt, <Bursche/Mädel>. Es ist an der Zeit, dass Ihr nach Darnassus heimkehrt. Die Priesterin Alathea ließ uns wissen, dass Ihr dorthin zur Ausbildung zurückkehren sollt. Es scheint, als wärt Ihr bereit, getestet zu werden, so wie jene, die dem Licht dienen. Ihr solltet Euch dorthin begeben, sobald Ihr könnt. Alatheas Nachricht besagte, dass sie im Tempel des Mondes auf Euch wartet. Viel Glück.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5676] = { id = 5676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rückkopplung" }
quests[5677] = { id = 5677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rückkopplung", description = "So gern ich Euch auch unsere eigenen speziellen Lehren des Lichts zeigen würde, so ist dies doch nicht an uns. Ihr müsst zurück nach Sturmwind, zu Eurer eigenen Art, {name}... zumindest vorerst. Glaubt mir, es war nicht böse gemeint. Wenn Ihr zur Hohepriesterin Laurena in die Kathedrale des Lichts zurückkehrt, werdet Ihr verstehen, worüber ich spreche... Die Zeit ist für Euer Volk gekommen, Euch auf die Zukunft vorzubereiten, Euch von den anderen abzuheben, die einem ähnlichen Weg folgen.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5678] = { id = 5678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rückkopplung", description = "Es ist an der Zeit für Euch, nach Sturmwind zurückzukehren. Eure Vorgesetzten dort haben Euch zur Ausbildung zurückgerufen. Und obwohl mich das ein wenig verstört, so sind Euer Volk und meines doch Verbündete und ich würde niemals Verrat an diesem Bündnis begehen.\n\nIch möchte Euch gegenüber offen sein...Mein Argwohn jeglicher arkanen Magie gegenüber, möge sie nun göttlich inspiriert sein oder nicht, ist immer noch stark in mir.\n\nIhr werdet verstehen, wovon ich spreche, wenn Ihr zu Eurer Kathedrale des Lichts zurückkehrt. Sprecht mit der Hohepriesterin Laurena, wenn Ihr dort ankommt.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5679] = { id = 5679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingende Seuche" }
quests[5680] = { id = 5680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwache" }
quests[5713] = { id = 5713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schuss, ein Treffer", description = "Ich war mit einer wichtigen Nachricht auf dem Weg nach Lor'danel, als ich von dem Furbolg Marosh und seinen Fährtenlesern angegriffen wurde. Während des Angriffs wurde ich vergiftet, wodurch ich kaum noch stehen konnte. Ich kann ein Gegengift herstellen, aber es wird eine Zeit dauern, bis es bereit ist.\n\nIch möchte Euch bitten, mich zu verteidigen, bis ich das Gegengift anwenden kann. Ich werde Euch, so gut es geht, mit meinem Bogen helfen.\n\nFalls wir überleben, kann ich meine Botschaft nach Lor'danel überbringen, während Ihr mit Onaeya bei Maestras Posten sprecht, um sie von diesem Vorfall zu unterrichten.", sourceObjective = "Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten im Eschental.", completion = "Ihr bringt sehr willkommene Neuigkeiten, {class}. Es ist gut zu hören, dass Aynasha lebt, und ich danke Euch dafür. Ich hoffe, dass Ihr eine Belohnung für Eure edlen Bemühungen annehmt. Möge Elune über Euch wachen und Euren Weg erleuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5721] = { id = 5721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Darroheim", description = "Nun, {name}, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim, und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", sourceObjective = "Legt das Reliktbündel auf den Marktplatz von Darroheim.\n\nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.\n\nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.\n\nBesiegt Rotpfad den Verderbten.\n\nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[5722] = { id = 5722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem verloren gegangenen Ranzen", description = "Die Troggs sind nicht das Einzige, das Magatha im Flammenschlund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird...und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.\n\nBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.\n\nBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar.", sourceObjective = "Sucht im Flammenschlund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5723] = { id = 5723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft des Feindes wird auf die Probe gestellt", description = "Unter der Stadt Orgrimmar haben stämmige Kreaturen, als Troggs bekannt, damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte Magatha Frieden mit diesen Kreaturen schließen wollen, doch die Troggs stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des Taurenvolks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte Horde.\n\nSie bittet Euch, der Gefahr durch die Troggs ein Ende zu machen, bevor sie die Horde von unten überwältigen. Geht zum Flammenschlund und vernichtet sie alle.", sourceObjective = "Sucht in Orgrimmar nach dem Flammenschlund, tötet dann 8 Flammenschlundtroggs und 8 Schamanen der Flammenschlundtroggs und kehrt anschließend zu Rahauro in Donnerfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5724] = { id = 5724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung des verloren gegangenen Ranzens", description = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.\n\nIhr befreit den Ranzen aus seinem Klammergriff und verstaut ihn bei Eurer eigenen Ausrüstung, dann bereitet Ihr Euch darauf vor, die Tunnel zu verlassen und zu Rahauro in Donnerfels zurückzukehren.", sourceObjective = "Bringt den Grimmtotemranzen zu Rahauro nach Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5725] = { id = 5725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die... weniger Visionen haben.\n\nEine Sekte des Schattenrates, die sich die Sengende Klinge nennt und sich in den Höhlen unterhalb Orgrimmars versteckt, ist ein Musterbeispiel dafür. Die Fürstin sagte mir, dass Mitglieder der Sengenden Klinge in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien... und sie möchte sich diese Bücher von ihnen 'borgen'. Ihr werdet sie ihr beschaffen.", sourceObjective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5726] = { id = 5726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Eines werde ich in meinen Reihen auf keinen Fall dulden, {name}: Verräter. Ich wäre allerdings töricht, würde ich meine Trümpfe einfach so ausspielen. Die Geschwüre der Verderbnis in unserem Land würden nicht tief genug herausgeschnitten und die Infektion würde sich noch verschlimmern.\n\nAber Ihr, ein junger Abenteurer, könntet dorthin gehen, wo es meinen Agenten nicht möglich ist... könntet die Wahrheit ans Licht bringen... herausfinden, wer wirklich hinter dieser Bestie steckt.\n\nWenn Ihr mutig genug seid, geht zur Knochenhöhle östlich von Orgrimmar, besorgt mir das Insigne eines Offiziers der Brennenden Klinge dort und kehrt zu mir zurück.", sourceObjective = "Bringt ein Insigne des Leutnants zu Thrall nach Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5727] = { id = 5727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Und jetzt lasst uns sehen, ob das Insigne, das Ihr gefunden habt, der Mühe wert ist.\n\nIn der Stadt gibt es einen Hexenmeister, der seiner Meinung nach mein Vertrauen genießt. Er weiß allerdings nicht, dass ich gewahr bin, wem er wirklich die Treue hält. Tatsächlich ist er der Anführer der Brennenden Klinge. Aber stürzt Euch jetzt nicht übereilt in einen Kampf mit ihm. Er könnte nützlich sein und wir werden ihn gegen unsere Feinde einsetzen.\n\nBringt dieses Insigne zu ihm in die Kluft der Schatten hier in Orgrimmar. Sprecht mit ihm, seht, ob er Euch für einen der Ihren hält, und kommt dann zu mir zurück.", sourceObjective = "Bringt Neeru Feuerklinge das Insigne des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Brennenden Klinge seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5728] = { id = 5728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Hmmm, Anführer der Sengenden Klinge... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr... Bazzalan, und der andere, den Neeru erwähnte... Was war er doch gleich, ein Hexenmeister? Sie müssen vernichtet werden.\n\nKehrt zur Kluft der Schatten zurück und begebt Euch in den Flammenschlund, {name}. Findet diese beiden Anführer der Sengenden Klinge und tötet sie. Aber seid vorsichtig, damit Neeru nicht erfährt, wer das getan hat. Er muss Euch auch weiterhin für <seinen Kampfgenossen/seine Kampfgenossin> halten.", sourceObjective = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5729] = { id = 5729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Ich glaube, unser nächster Schritt sollte sein, Euch in Neerus Nähe unterzubringen. Falls er wirklich so beunruhigt ist, wie die Berichte vermuten lassen, könnten wir zwei Fliegen mit einer Klappe schlagen. Erstens könntet Ihr mehr über den Rat oder zumindest die Sengende Klinge in Erfahrung bringen, und zweitens könnte er Euch möglicherweise genug vertrauen, um Euch zu bitten, ihm zu helfen. Vielleicht wird er Euch für jemanden halten, der die Lücken füllt, die der Tod der Anführer gerissen hat.\n\nKehrt zur Kluft zurück und sprecht noch einmal mit ihm, aber haltet Euch bedeckt.", sourceObjective = "Sprecht mit Neeru Feuerklinge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5730] = { id = 5730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Ihr seid einer meiner Offiziere! Macht Euch bereit, {class}. Ich werde Euch bald benötigen.\n\nDie Zeit, die ich für die Sengende Klinge aufgebracht hatte, war jetzt vielleicht reine Zeitverschwendung, aber das bedeutet nicht, dass die restlichen Pläne des Schattenrates darunter leiden müssen. Ich werde tun, was ich kann, um den Schaden hier im Flammenschlund zu begrenzen. In der Zwischenzeit sollen meine Agenten im Brachland und im Eschental mit der Arbeit an unserem neuesten Geheimplan beginnen. Kommt bald zu mir zurück.", sourceObjective = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5741] = { id = 5741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szepter des Lichts", description = "Die Anhänger der Brennenden Klinge in der Festung Donneraxt im Osten sollen Gerüchten zufolge das Szepter des Lichts von den Naga beschafft haben. Die Legenden besagen, dass das Szepter dazu fähig ist, ganze Städte unter den Ozeanen verschwinden zu lassen. Wir dürfen nicht zulassen, dass die Brennende Klinge solche Macht besitzt.\n\nUm das zu verhindern, müsst Ihr selbst das Szepter bergen! Es ist im Besitz eines Sehers der Brennenden Klinge, der das Szepter in einem der Wachtürme der Feste Donneraxt studiert.", sourceObjective = "Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.", sourceObjectiveStatus = "unverified-source-field" }
quests[5742] = { id = 5742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung", description = "Ihr habt sehr hart gearbeitet. Ruht Eure müden Knochen aus und erlaubt mir, mich korrekt vorzustellen.", sourceObjective = "Hört Euch an, was Tirion Fordring zu sagen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[5761] = { id = 5761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtung der Bestie", description = "Die vorrangige Aufgabe, die mir unser großer Kriegshäuptling übertragen hat, ist die Vernichtung der Kreaturen, die dafür verantwortlich sind, dass sich der dämonische Einfluss in der großen Stadt unseres Herrschers einnisten konnte. Die Kultisten der Brennenden Klinge sind eine Gefahr, aber es gibt auch noch andere. Die Anhänger der Sengenden Klinge zum Beispiel, die sich im Flammenschlund niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der Horde auf ihre Seite zu ziehen.\n\nUm sie aufzuhalten, muss ihr Anführer beseitigt werden - eine Teufelswache namens Taragaman der Hungerleider.\n\nTötet ihn, und sein Herz wird Thrall beschwichtigen, dessen bin ich mir sicher.", sourceObjective = "Begebt Euch in den Flammenschlund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Feuerklinge nach Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5762] = { id = 5762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hemet Nesingwary Jr.", description = "Ich habe hier eine Sendung für einen alten Kunden von mir, Hemet Nesingwary Jr., ein Zwerg. Die Sendung war wochenlang unterwegs und Hemet ist schon längst wieder weg. Er sagte, dass er ins Schlingendorntal gehen wolle, um die Bestien dort zu jagen, aber er ließ mir etwas Geld da und wollte, dass ich ihm seine Sendung schicke, sobald es mir möglich sei. \n\nJunior ist ein reicher Zwerg und man sollte sich mit den Reichen ruhig gut stellen, findet Ihr nicht auch? Also... könntet Ihr die Sendung für mich zustellen?\n\nWie ich hörte, hat er im Schlingendorntal nördlich von Grom'gol ein Lager aufgeschlagen.", sourceObjective = "Bringt Kravels Kiste zu Hemet Nesingwary Jr. ins Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5763] = { id = 5763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd im Schlingendorntal", description = "Vor langer Zeit kam ein Zwerg in dieses Land. Sein Name war Hemet, und er kam, um große Wildtiere zu jagen. Sein Geschick mit Flinten war außergewöhnlich, und wir haben viele Tage zusammen auf der Jagd verbracht. Sogar die Feindschaft zwischen unseren Völkern war vergessen.\n\nAls er ins Schlingendorntal ging, schwor ich, ihn irgendwann einmal wieder willkommen zu heißen. Er ist jetzt zum Jagen in ferne Länder gegangen, aber sein Sohn hat seinen Platz eingenommen.\n\nBringt Hemet Jr. dieses Kodohorn als Geschenk. Ihr findet ihn im Schlingendorntal, nördlich des Basislagers von Grom'gol.", sourceObjective = "Bringt Roons Kodohorn zu Hemet Nesingwary Jr. ins Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5781] = { id = 5781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von vergessenen Erinnerungen", description = "Wenn Ihr Taelan helfen wollt, zurückzubekommen, was er verloren hat, müsst Ihr Gegenstände aus seiner Vergangenheit zusammentragen.\n\nDer Erste dieser Gegenstände ist ein Spielzeug, das ich ihm zu seinem 7. Geburtstag schenkte. Es war sein wertvollster Besitz. Ein winziger Kriegshammer, die exakte Kopie meines eigenen.\n\nAls man mich wegen Verrats verbannte, erzählte ihm seine Mutter, dass ich gestorben sei. Man brachte ihn zu meinem angeblichen Grab beim Tiefgewölbe, wo er den Hammer zusammen mit seiner Erinnerung an mich begrub - für immer.\n\nIhr müsst Euch zum Tiefgewölbe begeben und Taelans Hammer holen.", sourceObjective = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5801] = { id = 5801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersäulen geschmiedet", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Krater von Un'Goro liegt der Feuersäulengrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Arbington sprechen.", sourceObjective = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.\n\nBringt den unvollendeten Dietrich dann zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5802] = { id = 5802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersäulen geschmiedet", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Krater von Un'Goro liegt der Feuersäulengrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Zitters sprechen.", sourceObjective = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.\n\nBringt den unvollendeten Dietrich zu Apotheker Zitters im Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5803] = { id = 5803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arajs Skarabäus", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, {name}!", sourceObjective = "Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5804] = { id = 5804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arajs Skarabäus", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, {name}!", sourceObjective = "Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Zitters im Bollwerk, in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5805] = { id = 5805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Merissa Stillbrunn in Goldhain einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Merissa Stillbrunn in Goldhain den Goldhaingeschenkgutschein.", sourceObjectiveStatus = "unverified-source-field" }
quests[5821] = { id = 5821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leibwache zu mieten", description = "Unter normalen Umständen würden Rigger und ich unseren Kodo an den Kolkarzentauren vorbeiführen. Aber ab und zu sind Kriegstrommeln der Zentauren zu hören, und dann machen wir sofort Halt. Es ist nicht gut fürs Geschäft, tot zu sein!\n\nIch sag Euch was, {class}, wenn Ihr uns heil am Dorf der Kolkar vorbeibringt, soll es Euer Schaden nicht sein.\n\nEs ist nur eine kurze Strecke und Ihr müsst lediglich dafür sorgen, dass die Karawane intakt bleibt, dann könnt Ihr Euch Eure Belohnung bei Smeed Schraubenbuddel abholen. Ihr findet ihn ein Stück weiter die Straße runter. Wir haben geschäftlich miteinander zu tun.", sourceObjective = "Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5841] = { id = 5841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Yori Bruchhelm in Kharanos einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Yori Bruchhelm in Kharanos den Geschenkgutschein von Kharanos.", sourceObjectiveStatus = "unverified-source-field" }
quests[5842] = { id = 5842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Orenthil Wisperwind in Dolanaar einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Orenthil Wisperwind in Dolanaar den Geschenkgutschein von Dolanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5843] = { id = 5843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Magga in Klingenhügel einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Magga am Klingenhügel den Geschenkgutschein des Klingenhügels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5844] = { id = 5844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Vorn Himmelsdeuter im Dorf der Bluthufe einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Vorn Himmelsdeuter im Dorf der Bluthufe den Geschenkgutschein der Bluthufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[5845] = { id = 5845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von verlorener Ehre", description = "Der Orden der Silbernen Hand wurde gar sehr geschwächt, als Uther sein gewaltsames Ende fand.\n\nDer Junge hat durchgehalten, solange er konnte. Er wurde bis zum vom Krieg zerrissenen Weiler Nordtal zurückgetrieben, und dort stellte er sich zu seinem letzten Kampf.\n\nWar noch irgendjemand aus dem Orden am Leben, fragte er sich - und spielte das überhaupt noch eine Rolle?\n\nMit diesem Gedanken im Kopf schmetterte Taelan die Standarte des Ordens zu Boden und entsagte allem, was er gelernt hatte. Auf dem blutgetränkten Boden des Nordtals ließ er seine Ehre zurück.\n\nIhr müsst ins Nordtal reisen und das Symbol der verlorenen Ehre finden.", sourceObjective = "Reist ins Nordtal im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5846] = { id = 5846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Liebe und Familie", description = "Als Taelan noch ein Kind war, unternahmen wir mit der Familie oft Ausflüge nach Darrowehr. Bei unserem letzten Besuch malte eine Künstlerin namens Renfray ein Porträt von uns, wie wir am Strand posierten. Das ist die schönste Erinnerung, die ich an Taelan und Karandra habe. Denn es war just dieser Moment, wo ich meine Frau und meinen Sohn in den Armen hielt, dass ich eine Liebe und Verbundenheit mit meiner Familie spürte, die ich seitdem nie wieder erlebt habe.\n\nFalls dieses Gemälde noch existiert, müsst Ihr es finden.\n\nBegebt Euch zur in Trümmern liegenden Insel Darrowehr und seht nach, ob das Gemälde der Künstlerin noch da ist.", sourceObjective = "Begebt Euch zur Insel Darrowehr im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5847] = { id = 5847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Claire Weidner in Brill einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Claire Weidner in Brill den Geschenkgutschein von Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[5848] = { id = 5848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Liebe und Familie", description = "Das Gemälde... Es hing jahrelang an der Wand meiner Werkstatt - in der Kaserne des Ordens.\n\nNachdem Tirions Prüfung vorüber war, wusste ich, dass ich das Gemälde nicht mehr dort für alle sichtbar hängen lassen konnte. So versteckte ich es an einem Ort, an dem es niemand vermuten würde.\n\nGeht nach Stratholme und begebt Euch tief in die heutige Scharlachrote Bastion. Sucht dort nach einem Gemälde, auf dem unsere Zwillingsmonde abgebildet sind. Kratzt die Farbe weg, bis mein Meisterwerk zum Vorschein kommt, 'Von Liebe und Familie'.\n\nMöge das Licht Eure Taten leiten.", sourceObjective = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\n\nBringt das Gemälde zu Tirion Fordring.", sourceObjectiveStatus = "unverified-source-field" }
quests[5861] = { id = 5861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myranda suchen", description = "Ihr habt alles getan, um das ich Euch bislang bat, {name}. Jetzt fehlt nur noch ein Schritt auf Eurem Weg zur Erlösung.\n\nIhr müsst die gesammelten Gegenstände Taelan aushändigen. Leider werden Euch Taelan und seine Scharlachroten Kreuzzügler angreifen, sobald sie Euer ansichtig werden.\n\nEs gibt nur eine Möglichkeit, meine Nachricht zu übermitteln, und zwar durch Täuschung.\n\nIm Süden findet Ihr Uthers Grabmal. Myranda, eine alte und getreue Vertraute von mir, lebt jetzt dort - geht zu ihr. Zeigt ihr die Gegenstände, dann wird sie Euch helfen.", sourceObjective = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.", sourceObjectiveStatus = "unverified-source-field" }
quests[5862] = { id = 5862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Täuschung", description = "Ich bin eine Illusionistin, wie Ihr das nennen würdet. Ich könnte zwar eine Illusion erschaffen, die es Euch ermöglichen würde, Herdweiler zu betreten, aber seid gewarnt, meine Kräfte haben Grenzen.\n\nSolltet Ihr Euch zu weit aus diesem Land entfernen, lassen die Effekte dieser Illusion nach. Der Zauber selbst bedarf Unmengen an Konzentration und Kraft meinerseits, und deshalb kann ich den Effekt nur für kurze Zeit aufrechterhalten.\n\nKommt wieder zu mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Myranda, um die Scharlachrote Illusion zu erhalten. Begebt Euch nach Herdweiler, während Ihr unter dem Einfluss der Scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.\n\nHerdweiler liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5863] = { id = 5863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Truppenlager der Dünenbrecher", description = "Erst kürzlich ist eine große Gruppe nomadischer Oger in Tanaris eingetroffen. Südlich von hier haben sie einen großen Bereich der Wüste in Besitz genommen und ein Truppenlager aufgeschlagen. Mehrere kleinere Gruppen durchstreifen momentan die Wüste, einige davon sind in die alten Trollruinen eingedrungen.\n\nDas Truppenlager der Dünenbrecher muss zerstört werden! Wir dürfen nicht zulassen, dass diese Oger zu einer Streitmacht heranwachsen.\n\nDer Anführer der Gruppe heißt Gor'marok der Verheerer. Ich bin mir sicher, dass es den Anfang vom Ende für die Oger bedeuten würde, wenn man ihnen den Anführer nimmt.", sourceObjective = "Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5881] = { id = 5881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinzurufen der Reserve", description = "Die Horde kümmert sich gut um ihre Truppen... seit dem großen Krieg ging es uns hier in Kalimdor sehr gut.\n\nIhr müsst mir einen Gefallen tun. Ich lasse einen Jungen namens Grish Fernläufer den Großen Aufzug im Südlichen Brachland bewachen. Gebt ihm diesen Brief, er wird ihn wissen lassen, dass ich einen Ersatzmann angefordert habe, um ihn von seinem Dienst zu entbinden, damit er seine Familie besuchen kann. Er bat mich vor einer Weile darum und wird sich über diese Nachricht freuen.", sourceObjective = "Maggran möchte, dass Ihr Grish Fernläufer am Großen Aufzug im Brachland einen Brief zustellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5882] = { id = 5882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Jagd" }
