quests[5892] = { id = 5892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisenschachtmine", description = "Bevor die Schlacht begann, lagerten wir Vorräte für Dun Baldar in der Eisenschachtmine. Die Troggs, die dort hausten, waren kein Problem solange wir Ersatztruppen hatten, die die Mine bewachen konnten, aber da wir nun gegen die Horde kämpfen, können wir sie nicht mehr kontrollieren.\n\nWir brauchen die Vorräte in der Eisenschachtmine, {name}. Betretet die Mine und bring mir eine Ladung.", sourceObjective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Allianz in Dun Baldar.", progress = "Habt Ihr die Vorräte, {name}? Wir können nicht genug davon haben!", completion = "Danke, {name}! Ich werde sie einem guten Zweck zuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5893] = { id = 5893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisbeißermine", description = "Die Eisbeißermine im Norden war einst ein idealer Ort, um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den Sturmlanzen nun härter werden, haben wir nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die Allianz oder an Untergrundvölker...\n\nAber wir benötigen dennoch unsere Vorräte, {name}! Geht zu der Eisbeißermine und bringt mir eine Ladung. Seid wachsam, was unsere Feinde anbelangt, die Übermacht in der Schlacht kann sich an jenem Ort schnell ändern...", sourceObjective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf.", progress = "Wart Ihr in der Eisbeißermine, {name}? Habt Ihr die Vorräte nach denen ich fragte?", completion = "Ah, Ihr habt Sie bekommen. Gute Arbeit, {name}! Die Vorräte sind schon etwas moderig, nachdem sie so lange in der Mine lagerten. Ich denke, sie werden uns dennoch sehr weiterhelfen.\n\nVielen Dank, {name}. Eure Anstrengungen sind lebenswichtig für die Versorgung unserer Streitkräfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5901] = { id = 5901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Also, um Schmerz und Unfrieden über den Scharlachroten Kreuzzug zu bringen, möchte ich ihnen ihr wertvolles Sägewerk wegnehmen. Ich bin mir sicher, der Verlust einer solchen Ressource wird ihnen ziemlichen Schaden in Bezug auf Verteidigung und Wiederaufbau der Stadt für ihre Zwecke zufügen. Werdet Ihr mir helfen, {name}?\n\nFangt an, indem Ihr diesen Krug zum Pestwald in den Östlichen Pestländern bringt. Füllt ihn mit den Termiten, die Ihr in ihren Hügeln überall im Wald findet. Kommt wieder, wenn Ihr eine ausreichende Menge habt.", sourceObjective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5902] = { id = 5902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Da wir jetzt jede Menge Termiten haben, bringt dieses stahlverstärkte Fass zum Sägewerk des Nordkamms südlich von Herdweiler. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes, irgendwo weit oben, vielleicht auf eine Kiste oder so was.\n\nNachdem Ihr es geöffnet habt, sollte sich der Rest von selbst erledigen. Kommt einfach hierher zurück und ich werde Euch dafür belohnen, dass Ihr mir geholfen habt.", sourceObjective = "Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den Westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[5903] = { id = 5903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Ich habe bereits viele Male versucht, den Scharlachroten Kreuzzug allein mit Gewalt auszulöschen, doch ohne Erfolg. Daher habe ich mich entschlossen, ihnen das Leben schwer zu machen.\n\nWenn Ihr bereit seid zu helfen, möchte ich, dass Ihr dieses Sägewerk mit der übelsten Termitenart verseucht, die je gefunden wurde.\n\nIm Pestwald, nahe dem einst großen Stratholme, gibt es eine Spezies, die die Seuche und auch die Geißel überlebt hat. Sucht ihre Hügel und füllt diesen Krug mit ihnen, damit wir sie darauf vorbereiten können, auf den Kreuzzug losgelassen zu werden.", sourceObjective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Nathaniel Dumah im Zugwindlager in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5904] = { id = 5904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Da wir jetzt die Termiten haben, bringt dieses stahlverstärkte Fass zum Sägewerk des Nordkamms südlich von Herdweiler. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes. Findet einen geeigneten Ort, vielleicht eine Kiste, und öffnet es dann. Die Termiten dürften dann ihre Arbeit tun und die Mühle für den Kreuzzug unbrauchbar machen.", sourceObjective = "Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den Westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[5921] = { id = 5921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondlichtung", description = "Alle Druiden sind in den hochheiligen Landen der Mondlichtung willkommen, ungeachtet der derzeitigen Spannungen im Zirkel des Cenarius zwischen dem Erzdruiden Hirschhaupt und dem Bewahrer Remulos, dem Wächter der Mondlichtung. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr das Wissen der Mondlichtung oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr zur Mondlichtung reisen und mit Dendrite Sternenschauer in Nachthafen über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", sourceObjective = "Benutzt den Zauber 'Teleportation: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5922] = { id = 5922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondlichtung", description = "Alle Druiden sind in den hochheiligen Landen der Mondlichtung willkommen, Tauren wie Nachtelfen. Bewahrer Remulos - der Wächter der Mondlichtung - wacht über alle Druiden, die hier ihren Winterschlaf halten. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr das Wissen der Mondlichtung oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr zur Mondlichtung reisen und mit Dendrite Sternenschauer in Nachthafen über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", sourceObjective = "Benutzt den Zauber 'Teleportation: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5923] = { id = 5923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave von Cenarius in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5924] = { id = 5924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave von Cenarius in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5925] = { id = 5925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave von Cenarius in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5926] = { id = 5926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5927] = { id = 5927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5928] = { id = 5928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5929] = { id = 5929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Bärengeist", description = "Im nordwestlichen Teil der Mondlichtung liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nachthafen zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", sourceObjective = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5930] = { id = 5930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Bärengeist", description = "Im nordwestlichen Teil der Mondlichtung liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nachthafen zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", sourceObjective = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5931] = { id = 5931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Darnassus", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Mathrengyl Bärenfährte bewegt sich wirklich im Einklang mit der Natur, selbst wenn er gefährlich nahe der Orte ist, an denen das Gleichgewicht zusammengebrochen ist. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", sourceObjective = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bärenfährte in der Enklave von Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[5932] = { id = 5932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Donnerfels", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Auch wenn die Tauren auf den Wegen des Cenarius als jung angesehen werden, wandelt Turak Runentotem doch mit großem Gleichgewicht in Gegenwart der Natur. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", sourceObjective = "Kehrt nach Donnerfels zurück und sprecht mit Turak Runentotem auf der Anhöhe der Ältesten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5941] = { id = 5941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Chromie", description = "Ihr habt viele Relikte der Schlacht von Darroheim gesammelt. Jedes Mal, wenn Ihr mit weiteren zurückgekehrt seid, sehnte sich mein Herz nach meinem Dorf... sehnte es sich danach, es vor seinem Schicksal zu bewahren.\n\nIch weiß, dass das nicht sein kann, aber Chromie, diese seltsame Gnomin in Andorhal, behauptet, es wäre möglich. Sie sagt, dass Ihr Darroheim retten könnt!\n\nSie hat mich gebeten, die Relikte zu sammeln und sie von Euch zu ihr bringen zu lassen. Sie sagte, dass sie Euch im zerstörten Gasthaus von Andorhal erwartet.", sourceObjective = "Bringt das Reliktbündel zu Chromie nach Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5942] = { id = 5942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckte Schätze", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, {name}. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", sourceObjective = "Bringt Josephs Schlüssel zu Josephs Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[5943] = { id = 5943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizeltons Karawane", description = "Ihr seht fähig aus, {race}. Vielleicht wollt Ihr Euch etwas Geld verdienen? Cork und ich haben mit dieser Karawane angefangen, um einen Haufen Geld zu scheffeln. Doch wir hatten keine Ahnung von den Gefahren, die das schnelle Geld mit sich bringen würde!\n\nDa vor uns liegt der Zirkel der Mannoroc...normalerweise ignorieren die Dämonen uns, aber dieses Mal verängstigt irgendetwas die Kodos. Ich werde Euch dafür bezahlen, wenn Ihr die Karawane auf dem Weg am Zirkel der Mannoroc vorbei beschützt. Sobald wir sicher daran vorbei sind, könnt Ihr Euch Eure Belohnung bei unserem Geschäftspartner Smeed in Schraubenbuddels Lager abholen.", sourceObjective = "Geleitet Gizeltons Karawane am Zirkel der Mannoroc vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5944] = { id = 5944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Träumen", description = "Über so lange Zeit war ich eine Marionette des Obersten Kreuzfahrers. Welchen Grund gab es, gegen das anzukämpfen, was aus dem Scharlachroten Kreuzzug geworden ist? Es ist Jahrzehnte her, doch die Erinnerungen an meinen Vater - diese kostbaren Erinnerungen - waren es, die mich am Leben erhielten.\n\nIch habe Träume, <Fremder/Fremde>. In diesen Träumen ist mein Vater bei mir. Er steht stolz an meiner Seite, während ich in den Orden aufgenommen werde. Wir bekämpfen Legionen der Geißel, Seite an Seite. Wir bringen der Allianz und Lordaeron Ehre.\n\nIch möchte nicht mehr träumen.\n\nBringt mich zu ihm.", sourceObjective = "Geleitet Taelan Fordring aus Herdweiler hinaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5961] = { id = 5961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Champion der Bansheekönigin", description = "Es freut mich sehr, dass sich die Kampferprobten unserer Sache anschließen. Unsere Schar gewinnt mit jedem Tag an Größe und Stärke. Vielleicht seid Ihr bereit, Euren Mut auf die Probe zu stellen, {class}?\n\nZu den ersten meiner Helden gehörte Nathanos, der heute Pestrufer genannt wird. In unseren Reihen gibt es kaum einen mit mehr Entschlossenheit oder Eifer.\n\nSucht in den Östlichen Pestländern nach ihm. Er wohnt in Marris Siedlung; ab und an streift er durch die dezimierten Ödländer und tötet jeden Abschaum der Geißel und der Allianz, den er aufspüren kann.", sourceObjective = "Sprecht mit Nathanos Pestrufer in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5981] = { id = 5981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tobende Riesen", description = "Vor rund 4.000 Jahren rettete Tyrande Wisperwind die Frostsäblerkönigin aus den Händen tobender Riesen. Seither sind die Frostsäbler Verbündete der Nachtelfen.\n\nDoch die Riesen, die einst eine Gefahr für die Frostsäbler waren, gibt es noch immer, und das nicht allzu weit von hier entfernt. Man nennt sie Frosthagelriesen und sie haben das große Tal südlich von hier für sich beansprucht.\n\nBeweist Eure Treue zu den Frostsäblern. Tötet diese Riesen im Namen der Frostsäblerkönigin Shy-Rotam!", sourceObjective = "Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6001] = { id = 6001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Herz", description = "Unmittelbar östlich von Auberdine liegen viele Mondkinhöhlen. In der Auberdine am nächsten gelegenen Höhle befindet sich ein Mondkinstein. Mondklaue, der Verteidiger des Steins, stellt sich Euch nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Mondstaub des Cenarius zu benutzen, {name}... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", sourceObjective = "Benutzt den Mondstaub des Cenarius mit dem Mondkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Mathrengyl Bärenfährte in Darnassus, wenn Ihr fertig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[6002] = { id = 6002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Herz", description = "Im Land westlich von Taurajo im Brachland - kurz bevor es in Mulgore übergeht - liegt ein Mondkinstein. Mondkin sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich Euch, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Lunarstaub des Cenarius zu benutzen, {name}... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", sourceObjective = "Benutzt den Lunarstaub des Cenarius mit dem Mondkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Turak Runentotem in Donnerfels, wenn Ihr fertig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[6004] = { id = 6004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Ich wurde als Späher ausgeschickt, um etwas Schaden anzurichten und die Kraft von Herdweilers Verteidigung auszukundschaften. Einige Leute der Allianz sind der Meinung, die kleine Stadt habe mehr als nur eine historische Bedeutung. Meine Aufgabe ist es nicht, diese Bedeutung in Frage zu stellen, aber dennoch sollte ich mich in meiner Verfassung erst erholen, bevor ich weitermache.\n\nWenn Ihr wollt, zahle ich Euch ein hübsches Sümmchen für Eure Hilfe. Fangt südlich von hier in dem Lager an, das sie in der Nähe des kleinen Bollwerks aufgeschlagen haben. Wenn Ihr stark genug seid, könnt Ihr mir vielleicht bei meinem vordringlichen Ziel helfen.", sourceObjective = "Tötet 2 Scharlachrote Sanitäter, 2 Scharlachrote Jäger, 2 Scharlachrote Magier und 2 Scharlachrote Ritter, bevor Ihr zu Kirsta Grubenschatten in den Westlichen Pestländern zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6021] = { id = 6021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr der Ausgestoßene", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.\n\nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen aus der Grube unten. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Westen.\n\nGeht dorthin und schaltet Zaeldarr aus, {name}. Ich habe seine Schandtaten satt!", sourceObjective = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des Hoffnungsvollen Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[6022] = { id = 6022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Töten zu einem bestimmten Zweck", description = "Ihr tötet zu einem bestimmten Zweck, solange Ihr in meiner Siedlung seid.\n\nEure erste Aufgabe ist es, meine Hunde zu füttern.\n\nNehmt diesen Mörser nebst Stößel und begebt Euch zu Corins Kreuzung. Dort angekommen findet Ihr Mitglieder der Geißel, die Ihr töten könnt, in recht großer Anzahl.. Aus ihren frischen Kadavern benötige ich lebendige Fäulnis. Nehmt diese lebendige Fäulnis, zermahlt sie im Mörser und lasst sie ruhen, bis sie gerinnt. Bringt die geronnene Fäulnis hierher.\n\nUnd bedenkt, Schwachkopf, dass lebendige Fäulnis der Untoten nicht lange 'lebendig' bleibt. Ihr müsst sie schnell töten!", sourceObjective = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[6023] = { id = 6023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Meine wahre Mission bestand darin, die äußeren Kräfte des Scharlachroten Kreuzzugs zu schwächen und dann Herdweiler zu infiltrieren, damit ich ihre Zahl abschätzen kann. In meiner Verfassung kann ich das immer noch nicht allein, vielleicht dürfte ich Euch ja erneut um Eure Unterstützung bitten, {name}? Bevor ich entdeckt wurde, konnte ich die Informationen sammeln, dass der Kreuzzug zwei wichtige Mitglieder hat, die das Rückgrat ihrer Streitkräfte außerhalb der Stadt bilden: Jägerin Radley und Dragoner Durgen. Tötet sie, das bringt uns schon weiter. Sie müssten am Pass von Herdweiler außerhalb der Stadtgrenze sein.", sourceObjective = "Besiegt Jägerin Radley und Dragoner Durgen, bevor Ihr zu Kirsta Grubenschatten in den Westlichen Pestländern zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6024] = { id = 6024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hameyas Bitte", description = "Tötet mich. Bevor es zu spät ist.\n\nIch bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Geschwister und ich verdorbenes Fleisch... und wir veränderten uns. Wir sind infiziert.\n\nIch spüre bereits die Worte des Lichs, der mich bedrängt, dass ich nach Zul'Mashar gehen und noch mehr von meinem Volk infizieren soll. Ich kann nicht widerstehen, daher verfasste ich diese Schriftrolle, ehe es um meine Willenskraft geschehen ist.\n\nIch habe hinter dieser Gruft eine Truhe neben einem Wagen in der Erde vergraben, aber nur mein Schlüssel kann sie öffnen. Ich habe den Schlüssel. Wenn Ihr meinen Schatz möchtet, sucht mich.\n\nTötet mich. Bevor es zu spät ist.", sourceObjective = "Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6025] = { id = 6025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Was? Wirklich? Ihr möchtet noch mehr wissen? Aber Ihr habt bereits so viel für mich getan, {name}. Ich kann Euch unmöglich darum bitten, an meiner statt nach Herdweiler zu gehen.\n\nSeid Ihr sicher, {name}? Herdweiler ist viel gefährlicher als der Pass - ich kann Euch weder Schutz noch Informationen geben, was Ihr da vorfinden könntet.\n\nAlso, wenn Ihr wirklich bereit seid, mir zu helfen, dann geht in die Stadt und sucht eine erhöhte Stelle, von der aus Ihr einen guten Überblick habt. Dort könnt Ihr ihre Zahl abschätzen und mir dann Bericht erstatten. Aber seid vorsichtig...", sourceObjective = "Geht nach Herdweiler, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Grubenschatten in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6026] = { id = 6026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist viel verlangt", description = "Diese Leute von der Argentumdämmerung haben den alten Smokey beauftragt, ein paar Abrissarbeiten für sie durchzuführen. Smokeys Mama hat keinen Trottel großgezogen. Wenn bares Gold auf den Tisch gelegt wird, ist Smokey stets zu Diensten. Das ist mein Motto!\n\nIch wäre bereit, den Profit mit Euch zu teilen, wenn Ihr mir ein wenig zuarbeiten wollt. Das ist der Plan: Ich geh rüber in den Pestwald und kennzeichne die Gebäude, die abgerissen werden müssen. Ihr sammelt die Komponenten für die Bomben. Wir treffen uns hier wieder, wenn Ihr alles habt. Abgemacht?", sourceObjective = "Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.\n\nFür diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6027] = { id = 6027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buch der Uralten", description = "{name}, ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf der Insel Ranazjar nordwestlich von hier in die Hand der Schlangenstatue. Dadurch wird jener gerufen, der das 'Buch der Uralten' beschützt. Dieses Buch birgt die Geheimnisse der Naga. Geheimnisse, die seit Jahrhunderten gewahrt werden. Bringt mir dieses Buch, dann werden wir mehr über unsere schuppigen Widersacher erfahren!", sourceObjective = "Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6028] = { id = 6028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bericht der Ewigen Warte", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung der Ewigen Warte. Ich muss Argentumoffizier Reinherz im Zugwindlager einen Fortschrittsbericht zukommen lassen. Das ist weit entfernt von hier am südlichen Rand der Westlichen Pestländer.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meiner Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihr zu bekommen!", sourceObjective = "Bringt den Bericht der Ewigen Warte zu Argentumoffizier Reinherz im Zugwindlager in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[6029] = { id = 6029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Everlook Report" }
quests[6030] = { id = 6030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürst Nicholas Zverenhoff", description = "Ein einsiedlerisches Medium namens Umbranse, das in dieser Gegend ansässig ist, hat der Argentumdämmerung ein literarisches Meistwerk geschenkt... es handelt sich vermutlich um die größte Sammlung mündlicher Überlieferungen, die je zu Papier gebracht wurde.\n\nFürst Nicholas Zverenhoff, einer der angesehensten Anführer der Dämmerung, ist ein brillanter Sprachwissenschaftler. Könntet Ihr ihm das für mich bringen - natürlich gegen eine Belohnung? Bei der Kapelle des Hoffnungsvollen Lichts, tief im östlichen Teil der Östlichen Pestländer - da hält er sich gerade auf.", sourceObjective = "Bringt das Buch 'Studien über das Geistsprechen' zu Fürst Nicholas Zverenhoff in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[6031] = { id = 6031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenstoff", description = "Wir in der Holzschlundfeste sind eigentlich ganz zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für das Geschäft.\n\nEs ist noch nicht lange her, da kam eine Nachtelfenfreundin, die einen Runenumhang trug, auf die Holzschlundfeste. Runenstoff ist bei uns selten, aber der Umhang war so edel, dass mein Volk jetzt von mir verlangt, mehr Runenstoffkleidung zu fertigen.\n\nWerdet Ihr mir Runenstoff bringen? Wenn Ihr mir ausreichend beschafft, gebe ich Euch etwas im Tausch dafür.", sourceObjective = "Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste.", progress = "Habt Ihr den Runenstoff? Mein Volk ist ganz gierig nach weiteren Kleidungsstücken aus Runenstoff!", completion = "Ah, Ihr habt den Stoff. Was für ein herrliches Material!\n\nDanke, {name}. Ihr seid ein wahrer Freund. Bitte nehmt dies als Gegenleistung.", sourceObjectiveStatus = "unverified-source-field" }
quests[6032] = { id = 6032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochheiliger Stoff", description = "Die Einwohner der Holzschlundfeste mögen das Gefühl von Runenstoff auf der Haut, aber er ist nichts Hochheiliges für uns. Mondstoff dagegen ist hochheilig.\n\nBringt mir einen kleinen Vorrat dieses heiligen Stoffs und ich lehre Euch eine geheime Schneidertechnik.", sourceObjective = "Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste.", progress = "Habt Ihr den Mondstoff dabei, {name}?", completion = "Ah, sehr gut. Dieser Mondstoff wird für Gewänder benutzt, die für unser Volk hochheilig sind. Danke, {name}. Jetzt werde ich Euch ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6041] = { id = 6041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Smokey Sings, I Get Violent", description = "Während Ihr die Vorräte gesammelt habt, habe ich einige meiner Leute die Geißelbauwerke kennzeichnen lassen, die wir abreißen müssen.\n\nSo ist der Plan: Ich gebe Euch zehn Stecken meines speziellen Präparats. Ihr bringt sie rüber in den Pestwald und platziert sie in den Geißelbauwerken, die für die Sprengung markiert wurden.\n\n<Smokey schnippt mit den Fingern.>\n\nBing! So einfach ist das.", sourceObjective = "Reist in den Pestwald, nordwestlich der Kapelle des Hoffnungsvollen Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.\n\nWenn Ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.\n\nÜbrigens, Smokeys spezielles Präparat ist recht...instabil.", sourceObjectiveStatus = "unverified-source-field" }
quests[6042] = { id = 6042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kleinen Ärgernisse des Un-Lebens", description = "Man kann keine zwei Schritte von diesem Hof runter, ohne auf eine dieser grässlichen Fledermäuse zu stoßen. Ich möchte die Hunde ausführen und die Geißel abschlachten können, ohne dass mich diese elenden, schmutzigen Fledermäuse behelligen. Ich habe Wichtigeres mit meiner Zeit anzufangen, als tagein, tagaus sinnlos Fledermäuse zu töten. Ihr allerdings nicht.\n\nWas? Eure Ausbildung? Das ist Eure Ausbildung! Jetzt geht mir aus den Augen und kommt erst zurück, wenn Ihr eine ordentliche Menge dieser geflügelten Dämonen getötet habt! Enttäuscht mich nicht.", sourceObjective = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr fertig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[6061] = { id = 6061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Für uns als Tauren ist es wichtig, dass wir den Traditionen unserer Vorfahren folgen und gegen mächtige Kreaturen kämpfen. Wenn wir diese Kreaturen bezwingen, können wir ihre Geister aufnehmen und näher bei der Erdenmutter sein.\n\nAuf dieselbe Weise hilft es uns, eins mit der Natur zu werden, wenn wir ein Tier zähmen, damit es an unserer Seite kämpft. Ihr werdet auch irgendwann lernen, ein Tier Eurer Wahl zu zähmen. Aber alles erfordert Übung und Ihr müsst noch viel lernen. Nehmt als erstes diese Zähmrute. Ihr müsst einen ausgewachsenen Ebenenschreiter zähmen.", sourceObjective = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6062] = { id = 6062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Es ist eine bewundernswerte Fertigkeit, wenn man über die Natur gebietet. Als Jäger müsst Ihr lernen, wie man Macht und Kraft benutzt, die jeder Kreatur Eurer Wahl innewohnt.\n\nEs ist nicht einfach, Kontrolle über ein Tier zu erlangen. Ihr müsst diese Aufgabe mit großer Entschlossenheit verfolgen.\n\nAls erste Aufgabe nehmt diese Zähmrute und zähmt damit einen scheckigen Terroreber. Ihr findet sie in der Nähe von Klingenhügel. Übt Eure Fertigkeiten im Kampf mit dem Eber an Eurer Seite und kommt dann zu mir zurück.", sourceObjective = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[6063] = { id = 6063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Als Jäger dürft Ihr niemals die Verantwortung vergessen, die Ihr tragt. Die Natur ist eine Kraft, die sich nicht Euren Wünschen beugt. Man muss sie respektieren und anerkennen als etwas Stärkeres als die eigene Existenz.\n\n{name}, Ihr müsst beweisen, dass Ihr das verstanden habt, bevor Ihr die Fähigkeit erwerben könnt, Euch ein Tier als Gefährten zu zähmen.\n\nEure erste Aufgabe ist es, diese Zähmrute zu nehmen. Mit ihr könnt Ihr einen Waldweberlauerer zähmen. Zähmt ihn und übt Eure Fertigkeiten als Jäger.", sourceObjective = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[6064] = { id = 6064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Hallo, <Bursche/Mädchen>! Ihr wollt also wissen, wie Ihr ein eigenes Tier bekommen könnt?\n\nGut, dann lasst uns anfangen. Wenn es um das Jagen geht, dann ist nichts wichtiger als Eure Ausrüstung, aber wir können ein andermal über meinen neuen Schrapnell-Blaster sprechen. Konzentrieren wir uns vorerst auf etwas, das Euch gewiss interessiert: ein Tier!\n\nAm besten lernt Ihr, wenn Ihr verschiedene Kreaturen als Gefährten ausprobiert und herausfindet, welche Ihr mögt. Sucht also einen großen Klippeneber und benutzt dann diese Zähmrute, um ihn zu zähmen.", sourceObjective = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.", sourceObjectiveStatus = "unverified-source-field" }
quests[6065] = { id = 6065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", sourceObjectiveStatus = "unverified-source-field" }
quests[6066] = { id = 6066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", sourceObjectiveStatus = "unverified-source-field" }
