quests[6074] = { id = 6074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[6075] = { id = 6075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[6076] = { id = 6076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[6081] = { id = 6081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es auszubilden.\n\nReist nach Orgrimmar. Dort müsst Ihr mit Ormak Grimmschlag sprechen, einem unserer angesehensten Jäger. Er wird Euch die Fähigkeit verleihen, Euer neues Tier auszubilden. Ihr findet ihn im Tal der Ehre.\n\nViel Glück, {name}.", sourceObjective = "Sprecht mit Ormak Grimmschlag in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[6082] = { id = 6082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Die letzte Kreatur, die Ihr zähmen müsst, wird dasselbe mit Euch versuchen: der gepanzerte Skorpid. Er schlägt schnell und selbstbewusst zu. Eine solche Macht zu kontrollieren ist Euer Schicksal als Jäger.\n\nWenn Ihr zurückkehrt verleihe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird Euren Befehlen gehorchen. Unter Eurer Kontrolle wird Euer Tier an Eurer Seite Erfahrung sammeln. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.Ihr erlernt:", sourceObjective = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6083] = { id = 6083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Der Vorteil, den Euch ein Tier gegen Eure Rivalen bietet, wird zur Kenntnis genommen, {name}! Wenn Ihr Kontrolle über eine andere Kreatur erlangt, erhöht Ihr Eure eigene Kraft. Euer Tier muss sozusagen Euer verlängerter Arm werden.\n\nDie nächste Aufgabe führt Euch vom Land weg. Ihr findet die nächste Kreatur in den Gewässern vor der Küste. Sucht jenseits von Sen'jin nahe den Echoinseln. Sucht nach einem lebhaften Krebs, der Brandungskriecher genannt wird. Benutzt die Zähmrute, um ihn zu zähmen und übt dann Eure Fertigkeiten.", sourceObjective = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[6084] = { id = 6084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Diese Klippeneber sind recht bullig. Vielleicht möchtet Ihr etwas mit ein wenig mehr Grazie? Na gut, da hab ich genau das Richtige. Südlich und östlich von hier findet Ihr große weiße Katzen, die man Schneeleoparden nennt. Genau wie bei einem elegant geschnitzten Gewehr verbirgt sich hinter dem wunderschönen Äußeren ein kräftiger Kämpfer, der extremen Schaden zufügen kann. Ihr werdet feststellen, dass sie wesentlich agiler und schneller als Euer gezähmter Eber sind.\n\nNehmt diese Zähmrute und findet heraus, wie Euch der Schneeleopard gefällt.", sourceObjective = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildherz in Kharanos zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6085] = { id = 6085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Vielleicht hättet Ihr gern eine Kreatur, die etwas mehr besitzt als nur rohe Kraft? Der Eisklauenbär ist ein ausgezeichneter Gefährte für einen angehenden Jäger wie Euch und östlich von Kharanos zu finden. Hier ist die Zähmrute. Probiert dieses Geschöpf als Euer Tier aus und findet heraus, wie es Euch gefällt!\n\nWenn Ihr zurückkehrt, gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man sie ganz nach Belieben ruft und wegschickt.Ihr erlernt:", sourceObjective = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.", sourceObjectiveStatus = "unverified-source-field" }
quests[6086] = { id = 6086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "{name}, Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr müsst die Fertigkeiten erlangen, es auszubilden.\n\nReist nach Eisenschmiede und sucht die Halle der Waffen. Dort müsst Ihr mit Belia Donnerstein sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Macht, Euer neues Tier auszubilden, also macht Euch auf den Weg, <Bursche/Mädchen>.\n\nBelia ist recht umgänglich, Ihr findet gewiss ihre Zustimmung. Viel Glück, {name}.", sourceObjective = "Sprecht mit Belia Donnerstein in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[6087] = { id = 6087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr besitzt einen feurigen Geist, Jäger, und brennt schon auf Eure nächste Herausforderung.\n\nAls nächste Aufgabe müsst Ihr einen Wolf, der als Präriepirscher bekannt ist, zum Gefährten gewinnen. Diese Kreatur ist flink und furchtlos. Wenn Ihr diese Bestie als Euer Tier wollt, müsst Ihr diese Eigenschaften ebenfalls erlangen.\n\nIm Kampf werdet Ihr lernen, wie Ihr und Euer Tier ein Team werdet. Letztendlich müsst Ihr wie ein Wesen handeln, Muskel an Muskel.\n\nHier habt Ihr die Zähmrute, {name}. Zähmt einen Präriepirscher und übt Eure Fertigkeiten.", sourceObjective = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6088] = { id = 6088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Die letzte Aufgabe, die ich für Euch habe, verlangt von Euch, dass Ihr eine Kreatur zähmt, die den Himmel bewohnt. Der Sturzflieger ist ein schwieriger Gegner, aber als Euer Verbündeter gibt er Euch seine scharfen Angriffe und seine bedrohliche Präsenz.\n\nWenn Ihr zurückkehrt gebe ich Euch durch den Willen der Erdenmutter die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.Ihr erlernt:", sourceObjective = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6089] = { id = 6089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Donnerfels. Dort müsst Ihr mit Holt Donnerhorn sprechen, einem unserer angesehensten Jäger. Wenn er Euch für würdig befindet, gibt er Euch die Fähigkeit, Euer neues Tier auszubilden.\n\nHolt hat die mächtigsten und gefürchtetsten Bestien von Azeroth bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der Erdenmutter ist stark. Ihr könnt viel von ihm lernen. Viel Glück, {name}.", sourceObjective = "Sprecht mit Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[6101] = { id = 6101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Auf die Vielfalt der Natur kann man sich verlassen, {name}. Sie ist insofern vorhersehbar, dass sie niemals gleich bleibt. Sie ist in konstantem Wandel.\n\nDie Aufgaben, die ich Euch gebe, werden Euch helfen, die enormen Unterschiede der Kreaturen zu erkennen, die Ihr als Eure Gefährten wählen könnt.\n\nNehmt diese Zähmrute und zähmt damit einen der pirschenden Nachtsäbler, die im Süden zu finden sind. Übt Eure Fertigkeiten als Jäger. Dann werdet Ihr die Übereinstimmungen und Unterschiede der Natur begreifen.", sourceObjective = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[6102] = { id = 6102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr habt zwei Kreaturen gezähmt, die am Boden leben, jetzt müsst Ihr eine zähmen, die am Himmel dahinzieht. Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen, die man westlich von hier findet. Übt Eure Fertigkeiten mit dieser mächtigen Eule an Eurer Seite.\n\nWenn Ihr zurückkehrt gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.Ihr erlernt:", sourceObjective = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[6103] = { id = 6103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Darnassus. Dort müsst Ihr mit Jocaste sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Fähigkeit, Euer neues Tier auszubilden, also sputet Euch.\n\nJocaste mag einen strengen Eindruck machen, freut sich aber stets, wenn sie den Aufstieg eines neuen Jägers verfolgen kann. Behandelt sie mit Respekt, dann wird sie Euch ebenso begegnen. Viel Glück, {name}.", sourceObjective = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[6121] = { id = 6121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Lektionen", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, {name}. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist zur Mondlichtung und sprecht mit Dendrite Sternenschauer. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", sourceObjective = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6122] = { id = 6122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die eigentliche Ursache", description = "Die Klippenquellfälle in Dunkelküste dienen als wichtigste Trinkwasserquelle in der Region. Ich fürchte, jetzt ist es die primäre Ursache des Gifts, das der dortigen Fauna schadet, besonders dem Wild. Holt mit diesem Gefäß etwas Wasser vom Höhleneingang, aber seid vorsichtig, inzwischen hausen gefährliche Naga in einer Höhle bei den Wasserfällen.\n\nWenn Ihr es gefüllt habt, bringt es zu Alanndarian Nachtweise in Auberdine. Sie bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihr dieses Übels annehmen.", sourceObjective = "Benutzt das leere Gefäß bei den Klippenquellfällen und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.\n\nBringt die gefüllte Probe der Klippenquellfälle zu Alanndarian Nachtweise nach Auberdine in Dunkelküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[6123] = { id = 6123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heilmittel sammeln", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für das Wild anrühre. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn wir Pech haben und Ihr keiner seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nUnd der besseren Wirksamkeit wegen brauche ich etwas Lunarfungus. Es ist recht leicht, Lunarfungusblüten zu finden. In den Höhlen östlich von hier gedeihen sie reichlich. Mondkin, die neuerdings recht gereizt sind, hausen in diesen Höhlen, also seid vorsichtig.", sourceObjective = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nachtweise in Auberdine, damit sie eine Heilsalbe machen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[6124] = { id = 6124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung der Kranken", description = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, {name}. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um Dunkelküste wimmelt es von krankem Wild. Heilt es mit der Salbe von seinem Übel.\n\nDendrite Sternenschauer bei der Mondlichtung wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius Auberdines Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", sourceObjective = "Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Klippenquells, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo das Eschental beginnt, aufgetaucht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[6125] = { id = 6125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht über Gift", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Mathrengyl Bärenfährte in Darnassus zurückkehren, {name}. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", sourceObjective = "Kehrt zu Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6126] = { id = 6126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Lektionen", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, {name}. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um...und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist zur Mondlichtung und sprecht mit Dendrite Sternenschauer. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", sourceObjective = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6127] = { id = 6127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die eigentliche Ursache", description = "Der Glutnebelgipfel nordwestlich des Wegekreuzes ist höchstwahrscheinlich die Quelle, von wo aus sich das Gift verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen. Dieses Wasser wurde vermutlich durch Dämonen anbetende Kultisten der Brennenden Klinge verunreinigt.\n\nEntnehmt dem Teich auf der Spitze des Gipfels mit diesem Behältnis eine Probe. Wenn es gefüllt ist, bringt es zu Tonga Runentotem beim Wegekreuz. Er bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihm dieses Übels annehmen.", sourceObjective = "Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.\n\nBringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runentotem beim Wegekreuz im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[6128] = { id = 6128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heilmittel sammeln", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für die Gazellen herstelle. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn Ihr nicht mit dieser Kunst vertraut seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nDer Wirksamkeit wegen brauche ich zuletzt Kodohörner – Splitter und Bruchstücke reichen aber nicht aus. Kodos, mit denen Ihr fertigwerdet, streifen durch den nördlichen Teil des Brachlands. Erlegt welche zum Wohle des Gleichgewichts, {name}, und bringt mir die Hörner.", sourceObjective = "Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runentotem beim Wegekreuz, damit er eine Heilsalbe machen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[6129] = { id = 6129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung der Kranken", description = "Ich konnte genügend Salbe für zehn heilende Dosen machen, {name}. Ich arbeite weiter mit den hiesigen Behörden zusammen und versuche, mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um das Nördliche Brachland wimmelt es von kranken Gazellen. Heilt sie mit der Salbe von ihrem Übel.\n\nDendrite Sternenschauer bei der Mondlichtung wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius unseren Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", sourceObjective = "Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße beim Wegekreuz gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6130] = { id = 6130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht über Gift", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Turak Runentotem in Donnerfels zurückkehren, {name}. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", sourceObjective = "Kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6131] = { id = 6131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Holzschlundfeste", description = "Die Einwohner der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Furbolgs der Holzschlundfeste auch kaum jemandem.\n\nSeid Ihr daran interessiert, Euch zu beweisen? Treibt den verderbten Stamm der Totenwaldfelle vom Teufelswald zurück, dann betrachten wir Euch eines Tages vielleicht als Verbündeten. Ihr findet den ersten Stamm der Totenwaldfelle - Krieger, Pfadfinder und Gärtner - westlich von hier.", sourceObjective = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 5 Krieger der Totenwaldfelle, 5 Pfadfinder der Totenwaldfelle und 5 Gärtner der Totenwaldfelle besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6132] = { id = 6132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt mich hier raus!", description = "Holt mich hier raus!\n\nIch kam ins Tal der Speere, um mit den Maraudines zu sprechen. Ich dachte, ich könnte Geschäfte mit ihnen machen... aber sie reden einfach nicht mit mir! Ich glaube, sie möchten mich eher verspeisen!\n\nHolt mich hier raus, mein Bruder Hornizz wird es Euch reich vergelten! Er ist in unserem Lager neben dem Kodofriedhdof im Osten.\n\nBeeilen wir uns, {name}. Es ist keine zwei Minuten her, da hörte ich einige Zentauren sagen, dass sie Holz für ihren Kochtopf sammeln möchten...", sourceObjective = "Eskortiert Melizza Brummsumms und sprecht anschließend mit Hornizz Brummsumms beim Kodofriedhdof Desolace.", completion = "Meine Schwester Melizza sagte, dass Ihr kommen würdet. Danke, dass Ihr sie aus dieser misslichen Lage befreit habt. Vermutlich steckt sie leider schon wieder in einer neuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6133] = { id = 6133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ersuchen des Waldläuferlords", description = "Die Hochelfen der Jagdhütte von Quel'Lithien haben etwas, das mir gehört, {class}: Ein Dokument, das mein Leben als Sterblicher schildert.\n\nBevor Ihr fragt, Ihr seid wahrscheinlich nicht befugt, derlei Informationen zu bekommen. Macht einfach, was ich Euch sage, Wurm: Holt den Lebenslauf zurück.\n\nUnd, Schwachkopf, richtet so viel Not und Elend an, wie Ihr könnt. Lasst sie leiden...", sourceObjective = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[6134] = { id = 6134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterplasmasuche", description = "Im Südosten liegt ein Tal, das Tal der Knochen, das von den Geistern der Magram heimgesucht wird. Klingt gruselig, nicht wahr? Stellt Euch mal vor, wie sich die Magram erst gruseln müssen! Wenn wir Geisterenergie an jenem Ort einfangen könnten, wäre das den Zentauren sicher einiges wert.\n\nHier, nehmt diese Kiste mit Geistermagneten. Wenn Ihr einen zwischen den beiden großen Skeletten im Tal aufstellt, den toten Goliaths, dann werden sich Geister materialisieren und dorthin gehen. Nehmt Abstand, schaltet die Geister aus und holt Euch ihr Geisterplasma - das verkaufen wir den Magram.", sourceObjective = "Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brummsumms in Desolace.", progress = "Wo ist mein Geisterplasma, {name}?", completion = "Da ist es! Sieht aus, als hättet Ihr auch etwas davon abbekommen. Irgendwie schleimig, hm?\n\nJedenfalls vielen Dank für Eure Mühe, {name}. Dieses Zeug ist ein Vermögen wert... wenn ich die Zentauren überzeugen kann, dass es echt ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[6135] = { id = 6135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerschwinge, oh, wie ich Euch hasse...", description = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid.\n\nIhr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid. Ja... ja, Schwachkopf, vielleicht seid Ihr wirklich für anspruchsvollere Missionen bereit.\n\nDämmerschwinge, der Albinofledermausdämon, streift nördlich von hier durch das Land. Spürt ihn auf und besiegt ihn. Kehrt mit einem Büschel seines weißen Fells zu mir zurück und Ihr sollt eine Belohnung erhalten.", sourceObjective = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Pestrufer.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.", sourceObjectiveStatus = "unverified-source-field" }
quests[6136] = { id = 6136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Korpulente", description = "Hinter der Kapelle des Hoffnungsvollen Lichts, dem Lager der Argentumdämmerung, und westlich vom Nordtal, findet Ihr die wohlbeleibte Madenbestie Blutschlinger.\n\nIch habe ganze Regimenter an dieses Monster verloren. Sein Leibesumfang ist gewaltig! Und je mehr er frisst, um so größer wird er...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr der Sieger wärt. Man weiß, dass Blutschlinger schon andere verschlungen hat, die töricht genug waren, ihn anzugreifen.", sourceObjective = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Pestrufer zurück, sobald Ihr diese Mission erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6141] = { id = 6141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder Anton", description = "Bruder Anton, mein Waffenbruder, hörte Gerüchte über einen Angriff der Untoten im fernen Kalimdor, in einem Land, das Desolace genannt wird. Anton buchte sofort eine Überfahrt dorthin, um die Bedrohung durch die Untoten zu lokalisieren und zu beseitigen!\n\nEr sucht Leute mit viel Tapferkeit und Entschlossenheit, die ihm dabei helfen. Wenn Ihr aufrichtigen Herzens seid, dann sprecht mit Anton. Er befindet sich in Desolace in einer Stadt der Allianz namens Nijelspitze.", sourceObjective = "Sprecht mit Bruder Anton in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[6142] = { id = 6142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muschelköder", description = "Ihr seht wahrlich aus wie ein Angler, {class}! Ich angle zu gern - schon mein Leben lang. Als Köder eignet sich das Fleisch der weichschaligen Muschel am besten. Die Fische können ihm einfach nicht widerstehen. Wisst Ihr, was ich meine?\n\nOben im Norden findet Ihr ein Schiffswrack vor der Küste. In der Gegend wimmelt es von weichschaligen Muscheln. Wenn Ihr mir 10 Teile Fleisch der weichschaligen Muschel bringt, werde ich Euch etwas dafür geben.", sourceObjective = "Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Schattenflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[6143] = { id = 6143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere Fische zu grillen", description = "Vielleicht habt Ihr es ja gehört, vielleicht auch nicht... meine Besatzung und ich waren vor der Insel Ranazjar fischen, nördlich des Schiffswracks vor der Küste im Norden. Wir haben immer dort gefischt, jetzt suche ich nur eine Möglichkeit, wie ich meine gefallenen Kameraden rächen kann.\n\nDie Naga haben uns eines Morgens angegriffen und alle außer mir getötet.\n\nDie Schuld lastet mir schwer auf der Seele, {class}; ihr müsst losziehen und diese Naga für mich grillen. Ich werde Euch für die Mühe belohnen. Meint Ihr, Ihr könnt mir behilflich sein?", sourceObjective = "Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Schattenflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[6144] = { id = 6144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl", description = "Der Befehl ist gekommen, {class}. Bragor Blutfaust selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission nach Unterstadt schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort nach Unterstadt und erstattet Bragor Blutfaust Bericht. Macht mir keine Schande, {class}!", sourceObjective = "Reist nach Unterstadt und sprecht mit Bragor Blutfaust.", sourceObjectiveStatus = "unverified-source-field" }
quests[6145] = { id = 6145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Purpurrote Kurier", description = "So wie niemand ohne den Kopf überleben kann, kann der Kopf nicht ohne den Körper überleben. Die Verteidigungsanlagen des Scharlachroten Kreuzzugs in Stratholme sind fast unüberwindbar. Stattdessen müssen wir den Körper unter dem Kopf abschneiden.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale nach Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, {race}! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", sourceObjective = "Kehrt in die Östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des Obersten Kreuzfahrers.\n\nBringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6146] = { id = 6146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nathanos' List", description = "Ich habe diesen Befehl etwas modifiziert. Sollte unsere kleine List wirken, wird das Scharlachrote Orakel schutzlos sein und wir schlagen zu!\n\nPasst jetzt genau auf, {class}. Ihr werdet diesen Befehl dem Kreuzzüglerlord Valdelmar überbringen.\n\nWie? Ihr drückt ihm das Ding in die Hand, Schwachkopf.\n\nBringt den Befehl und diesen faulen Apfel nach Tyrs Hand. Wenn Ihr in der Stadt seid, dann esst den Apfel. Ihr werdet Euch in etwas verwandeln, das für Menschen...verträglicher ist. Nehmt den Befehl und übergebt ihn dem Kreuzzüglerlord Valdelmar.", sourceObjective = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des Obersten Kreuzfahrers.", sourceObjectiveStatus = "unverified-source-field" }
quests[6147] = { id = 6147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Nathanos zurück.", description = "Der Oberste Kreuzfahrer bringt eine ungewöhnliche Bitte vor. Hrm, wie dem auch sei... was er verlangt, soll geschehen. Kehrt zur Scharlachroten Bastion zurück und lasst ihn wissen, dass das Orakel sich bald auf den Weg machen wird.\n\nWir werden alle Vorsichtsmaßnahmen treffen, damit sie es unbeschadet nach Stratholme schafft.", sourceObjective = "Kehrt mit der neuen Information zu Nathanos Pestrufer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6148] = { id = 6148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das scharlachrote Orakel Demetria", description = "Demetria ist die oberste Beraterin des Obersten Kreuzfahrers. Ihrer 'überirdischen' Sinne wegen nennt man sie das Orakel. Sie hat den Kreuzzug erfolgreich zu mehreren Siegen gegen die Geißel geführt.\n\nWir konnten sie zwar mit dieser List herauslocken, aber wenn sie wirklich eine übersinnliche Begabung besitzt, wird sie zweifellos mit Ärger rechnen. Ihr werdet für diesen 'Ärger' sorgen.\n\nSpürt das Orakel auf und beendet ihre Existenz. Sie müssten in diesem Moment von Tyrs Hand aufbrechen. Macht mich stolz, Wurm.", sourceObjective = "Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr erfolgreich wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[6161] = { id = 6161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt Rackmores Schatz!", description = "Aus Rackmores Logbuch geht hervor, dass sein Schiff zur Mondfederfeste segelte, als es von seefahrenden Kreaturen angegriffen wurde. Er versteckte seine Truhe auf der Insel Ranazjar, damit sein Schatz dem Feind nicht in die Hände fallen sollte.\n\nZwei Schlüssel, ein silberner und ein goldener, sind erforderlich, um die Truhe zu öffnen. Diese Schlüssel gingen verloren, doch wenn Schlüssel und Truhe gefunden werden, winkt ein Schatz!", sourceObjective = "Sucht Rackmores Silberschlüssel. Sucht Rackmores Goldschlüssel. Sucht und öffnet Rackmores Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6162] = { id = 6162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Ehemanns letzter Kampf", description = "Mein Gatte reiste unserem Klan zu Ehren durch den Teufelswald und kämpfte gegen den Schattenrat und andere verderbte Monstrositäten!\n\nAls er dem Tod viele Male entronnen war, erhielt ich einen Brief von ihm, in dem stand, dass ein Druide ihn um Beistand gegen einen großen beschmutzten Furbolg namens Oberanführer Ror gebeten hatte - man hörte nie wieder etwas von ihnen.\n\nIch möchte die Klauenhand dieses Ror, {name}. Er soll dafür büßen, dass er mich zur Witwe gemacht hat! Ich glaube, die Kreatur ist im Süden... nahe der Grenze des Eschentals.", sourceObjective = "Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.", sourceObjectiveStatus = "unverified-source-field" }
quests[6163] = { id = 6163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramstein", description = "Ich war überwältigt. Ich stand in dieser Siedlung... und blieb standhaft bei der Verteidigung von Lordaeron. Der Hof und alles darauf wurde von einer gigantischen Welle der Geißel belagert.\n\nDer Dreck. Der Schmutz. Er stand über mir und die Eingeweide hingen ihm aus einem klaffenden Loch in der Brust.\n\nIch erwachte als Geißel. Lange Zeit war ich hilflos. Meine Gedanken waren mit denen des Lichkönigs verschmolzen.\n\nSie kam zu mir... irgendwo, irgendwie wusste ich es. Frei.\n\nDoch jetzt muss ich meine Rache haben - Rache an dem, der mir das Leben genommen hat. Vernichtet ihn.", sourceObjective = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos.", sourceObjectiveStatus = "unverified-source-field" }
quests[6164] = { id = 6164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Quittungsbuch", description = "Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", sourceObjective = "Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal.", sourceObjectiveStatus = "unverified-source-field" }
quests[6181] = { id = 6181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eilige Nachricht", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Thor, unseren Greifenmeister. Er ist unten am Hügel; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", sourceObjective = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[6182] = { id = 6182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erste und Letzte", description = "Nathanos Marris war der erste und letzte Waldläuferlord der Menschen. Ein Schüler von Sylvanas Windläufer, die heute Bansheekönigin der Verlassenen ist.\n\nWir dachten, Nathanos sei fünf Jahre zuvor bei der Verteidigung von Lordaeron in der Schlacht gefallen. Sein Leichnam wurde zwar nie gefunden, aber man ging davon aus, dass er es nicht aus den Östlichen Pestländern hinaus geschafft hatte.\n\nMathias Shaw hat sein Verschwinden untersucht und könnte neue Informationen haben. Meldet Euch sofort bei ihm. Er lebt in der Altstadt, in der Kaserne.", sourceObjective = "Sprecht mit Meister Mathias Shaw in der Altstadt von Sturmwind. Er wohnt in der Kaserne.", sourceObjectiveStatus = "unverified-source-field" }
quests[6183] = { id = 6183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehret die Toten", description = "Fünf meiner besten Agenten wurden dem Fall Marris zugeteilt. Einer kam zurück und starb drei Tage später im Schlaf.\n\nDie wenigen Informationen, die wir aus ihm herausbekamen, waren unverständliches Gestammel. Wir haben zwei Worte verstanden: 'Nathanos' und 'Pestrufer'.\n\nIch habe nicht genügend Leute, um die Ermittlungen fortzusetzen, und Rabenholdt ist uns nicht behilflich. Wir müssen der Sache auf den Grund gehen, und wenn es nur ist, damit wir den Familien der Verstorbenen Trost spenden können. Werdet Ihr helfen?", sourceObjective = "Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6184] = { id = 6184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flint Schattenmoor", description = "Die einzige Information, die wir bislang haben, ist die, dass Nathanos Marris von diesem Pestrufer ermordet worden sein könnte. Wir gehen davon aus, dass Pestrufer derselbe Teufel ist, der meine Agenten beseitigt hat.\n\nFlint Schattenmoor, ein weiterer Agent des SI:7, ist im Lager der Allianz an der Zugwindspitze in den Westlichen Pestländern stationiert. Sucht ihn auf. Er wird Euch in die aktuelle Situation in den Pestländern einweihen und Euch einen Auftrag erteilen.\n\nViel Glück, {name}.", sourceObjective = "Reist zur Zugwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Schattenmoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[6185] = { id = 6185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Östlichen Pestländer", description = "Wie gesagt, Eure erste Mission ist eine Aufklärungsmission. Nichts Kompliziertes, {name}. Ihr müsst in die Östlichen Pestländer reisen und nach Hinweisen auf diesen Pestrufer suchen.\n\nHaltet nach Informationen über unsere vermissten Agenten Ausschau. Wir müssen davon ausgehen, dass sie tot sind, und wenn sie tot sind, muss es Leichen geben...irgendwo.\n\n<Flint schluckt schwer.>\n\nAlle SI:7-Agenten tragen diese Insignien.\n\n<Flint zeigt Euch seine SI:7-Insignien.>\n\nBringt alle zu mir zurück, die Ihr finden könnt.", sourceObjective = "Sucht in den Östlichen Pestländern nach Hinweisen auf den 'Pestrufer' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Schattenmoor an der Zugwindspitze.", sourceObjectiveStatus = "unverified-source-field" }
quests[6186] = { id = 6186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pestrufer kommt", description = "<Flints Gesicht wird schlagartig leichenblass.>\n\nNa... Nathanos ist das gewesen? Nathanos ist der Pestrufer?\n\nWarum? Er war... war so edel – ein Waldläuferlord, den alle geachtet haben. Der einzige Mensch, der je bei den Hochelfen ausgebildet wurde. Der soll jetzt ein ruchloser Agent der Verlassenen sein?\n\nIch... Ich bin untröstlich, dass ich das von Euch verlangen muss, {name}, aber König Wrynn muss unverzüglich über diese Wendung der Ereignisse informiert werden. Bitte kehrt nach Sturmwind zurück und überbringt diese Nachricht.", sourceObjective = "Kehrt nach Sturmwind zurück und informiert König Varian Wrynn über das Schicksal von Nathanos Marris.", sourceObjectiveStatus = "unverified-source-field" }
quests[6187] = { id = 6187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung muss wiederhergestellt werden", description = "Wisst Ihr, wie viele Waldläuferlords es auf dieser Welt gibt? Wie viele menschliche Waldläuferlords jemals existiert haben?\n\nNathanos' Errungenschaften waren beispiellos. Er war ein taktisches Genie und führte die Allianz in einem Jahrzehnt der Konflikte zu vielen Siegen.\n\nUnd jetzt... der Held der Verlassenen.\n\nNein. Das darf nicht sein. Die Ordnung muss wiederhergestellt werden.\n\nVersammelt eine Armee, {name}. Kehrt mit Eurer Armee in die Pestländer zurück und vernichtet den Pestrufer.\n\nIch wünsche Euch Glück, {name}. Das werdet Ihr für diesen Kampf wahrlich brauchen.", sourceObjective = "Stellt eine Armee auf und reist zu den Östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Pestrufer und jeden Abschaum der Horde, der ihn beschützen mag.\n\nBewahrt einen klaren Kopf, {name}. Die Horde wird den Waldläuferlord mit dem Leben verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6221] = { id = 6221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totenwaldfelle des Nordens", description = "Direkt südwestlich von hier liegt ein Furbolglager der Totenwaldfelle. Ich bin nicht sicher, was sie vorhaben, aber ich würde dem gern einen Riegel vorschieben, ehe es zum Problem wird.\n\nDer Stamm der Totenwaldfelle ist böse, aber die Verderbnis ist es, die ihre Hirne verseucht. Ihre Feindseligkeit ist keine angeborene Eigenschaft, doch da kann man nichts machen. Aus diesem Grund stimmt es mich zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss.\n\nBitte, {name}, tut, was getan werden muss, aber erspart mir die Einzelheiten. Sie beunruhigen mich zu sehr.", sourceObjective = "Nafien möchte, dass Ihr 5 Höhlenbehüter der Totenwaldfelle, 5 Rächer der Totenwaldfelle und 5 Schamanen der Totenwaldfelle besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6241] = { id = 6241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktivität der Winterfelle", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, {name}. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber wenn möglich andere Furbolgstämme.\n\nIn letzter Zeit ist mir aufgefallen, dass der Winterfellstamm uns gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.\n\nWenn Ihr ihre Anzahl reduzieren könntet, würde uns das sehr helfen, {name}.", sourceObjective = "Salfa möchte, dass Ihr 6 Totemiker der Winterfelle, 6 Höhlenbehüter der Winterfelle und 6 Pfadfinder der Winterfelle erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6261] = { id = 6261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Trinkfest", description = "{name}, ich habe alles, worum Lewis gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Thor in Westfall gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Lewis. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Westfall ohne neue Ausrüstung sind!", sourceObjective = "Bringt Osrics Kiste zu Dungar Trinkfest dem Greifenmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[6281] = { id = 6281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Sturmwind", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Lewis' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", sourceObjective = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[6282] = { id = 6282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpyien drohen", description = "Tauren sind die stolzen Beschützer dieser Länder. Zweifellos könnt Ihr erraten, warum mich die Anzahl der Harpyien hier im Steinkrallengebirge so beunruhigt.\n\nDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in Kalimdor. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen.\n\nIhr müsst die Harpyien für mich dezimieren, {name}!", sourceObjective = "Maggran Erdbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6283] = { id = 6283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfuriengeschlecht", description = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!\n\nFür diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.\n\nGeht zurück zum Verbrannten Tal, dort findet Ihr sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein, aber die Belohnung ist groß.", sourceObjective = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6284] = { id = 6284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnophobia" }
quests[6285] = { id = 6285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Lewis", description = "Der Greifenmeister in Westfall heißt Thor. Falls Ihr schon mit ihm gesprochen habt, dann könnt Ihr einen meiner Greifen zu ihm bringen.\n\nDas hier sollte man unbedingt wissen: Greifen sind stets so ausgebildet, dass sie in ihre Hauptstadt fliegen, aber sie bringen Euch nur zu einem außerörtlichen Greifenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nIhr seid bereits bei Thor gewesen, sprecht daher einfach wieder mit mir, wenn Ihr bereit seid, einen Greifen nach Westfall zu nehmen. Dort könnt Ihr Osrics Kiste bei Rüstmeister Lewis abliefern.", sourceObjective = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6301] = { id = 6301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zyklus der Wiedergeburt", description = "Industrielle Gier und ständige Kriege haben die Länder des Steinkrallengebirges verwüstet. Nur der Segen der Erdenmutter kann solch eine Verletzung heilen.\n\n{name}, Ihr müsst für mich ein spezielles Samenkorn suchen, Gaeasamenkorn. Man findet diese Samenkörner nur hier im Steinkrallengebirge, nördlich von Sonnenfels am Mirkfallonsee, in der Nähe des Ufers.\n\nWenn Ihr mir die Samenkörner bringt, werde ich sie auf magische Weise mit schamanistischer Macht erfüllen, um ihr Wachstum zu beschleunigen.", sourceObjective = "Tammra Windfeld in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6321] = { id = 6321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für Brill", description = "Exekutor Zygand bat mich, eine Inventur unserer Ausrüstung hier in Brill durchzuführen. Da die Geißel und Schlimmeres in den Wäldern lauert, möchte er nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen.\n\nIch habe festgestellt, dass wir im Großen und Ganzen gut bestückt sind, aber wir brauchen mehr Waffen als Ersatz für die, die wir auf dem Feld verloren haben.\n\nHier eine Anforderungsliste der benötigten Dinge für den Waffenhändler Gordon Wendheim in Unterstadt. Bringt die Anforderungsliste zur Fledermausführerin Anette und sprecht mit ihr über den Transport nach Unterstadt.", sourceObjective = "Bringt Morris' Anforderungsliste zu Fledermausführerin Anette.", progress = "Ihr scheint in offizieller Angelegenheit hier zu sein...", completion = "Ah, eine Anforderungsliste für Vorräte. Die solltet Ihr wohl nach Unterstadt bringen. Und zwar rasch, denn Brill darf nicht unterversorgt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[6322] = { id = 6322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Michael Garrett", description = "Ich habe den Nachschub für Brill in diese Kiste getan. Wenn Ihr Brill schon besucht und mit der Fledermausmeisterin gesprochen habt, könnt Ihr auf einer Fledermaus zu ihr reiten.\n\nSprecht mit Michael Garrett, dem Fledermausmeister von Unterstadt. Er kann Euch eine Fledermaus nach Brill zur Verfügung stellen.", sourceObjective = "Bringt Gordons Kiste zu Michael Garrett.", progress = "Wenn Ihr weite Strecken reisen müsst, dann ist eine Fledermaus das ideale Transportmittel.", completion = "Diese Kiste muss schleunigst nach Brill? Nichts leichter als das, unsere Fledermäuse fliegen täglich dorthin.", sourceObjectiveStatus = "unverified-source-field" }
quests[6323] = { id = 6323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Unterstadt", description = "Eine meiner Fledermäuse kann Euch nach Unterstadt bringen. Normalerweise kosten diese Flüge eine geringe Gebühr, aber der Flug nach Unterstadt ist für <einen tapferen Streiter/eine hübsche Dame> wie Euch kostenlos, {race}. Sprecht mich wieder an, wenn Ihr bereit seid, damit wir Euren Transport arrangieren können.\n\nIhr findet Gordon Wendheim im Handwerksviertel von Unterstadt. In diesem Viertel landet auch meine Fledermaus.", sourceObjective = "Bucht einen Fledermausritt zur Unterstadt bei Fledermausführerin Anette und bringt dann Morris' Anforderungsliste zu Gordon Wendheim in Unterstadt.", progress = "Ich halte meine Waffen in einem Top-Zustand. Sie sind gereinigt und einsatzbereit.", completion = "Eine Anforderungsliste aus Brill? Wohlan denn. Es ist eine Ehre, denen zu dienen, die unserer Dunklen Fürstin dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6324] = { id = 6324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Morris", description = "Der Fledermausmeister in Brill ist Fledermausführerin Anette. Wenn Ihr schon bei ihr gewesen seid, dann gebe ich Euch eine Fledermaus, damit Ihr zu ihr fliegen könnt.\n\nUnsere Fledermäuse fliegen stets nach Unterstadt, aber um zu entlegeneren Orten zu reisen, muss ihr Reiter zuerst die Gegend besuchen und mit dem dortigen Fledermausmeister sprechen.\n\nIhr habt Anette in Brill getroffen, daher könnt Ihr jetzt mit Fledermäusen dorthin fliegen. Sprecht wieder mit mir, wenn Ihr bereit seid.", sourceObjective = "Bucht einen Fledermausritt nach Brill bei Fledermausmeister Michael Garrett und bringt dann Gordons Kiste zu Todeswache Morris in Brill.", progress = "{name}, Ihr kehrt zurück. Habt Ihr unseren Nachschub aus Unterstadt?", completion = "Gute Arbeit, {name}. Diese Waffen gewährleisten, dass unsere Todeswachen nicht unvorbereitet überrascht werden.\n\nIhr habt der Dunklen Fürstin einen wertvollen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6341] = { id = 6341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Darnassus", description = "Alle in Dolanaar sind so stolz auf Schwester Aquinne. Ich bin sicher, sie wird sich sehr freuen, dieses aufmerksame Geschenk von Nyoma zu erhalten.\n\nWenn Ihr bereit seid, nach Darnassus zu reisen, sprecht einfach wieder mit mir und für ein paar Münzen könnt Ihr einen Hippogryphen mieten, der Euch dorthin bringt. Man sagte mir, Schwester Aquinne genießt die Abgeschiedenheit eines kleinen Platzes südlich vom Hippogryphenmeister in Darnassus. Sucht dort nach ihr, wenn Ihr angekommen seid.", sourceObjective = "Sprecht mit Fidelio, um einen Flug nach Darnassus zu erstehen, und bringt dann die Rezeptsammlung von Dolanaar zu Schwester Aquinne in Darnassus.", progress = "Wie kann ich Euch helfen?", completion = "Etwas für mich? Wer das wohl geschickt hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[6342] = { id = 6342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwartetes Geschenk", description = "Das ist wundervoll! Genau das Richtige, um mich während meiner Studien im Tempel des Mondes an mein Zuhause zu erinnern. Ich werde eins der Rezepte heute Abend ausprobieren. Ich kann es kaum abwarten!\n\nWürdet Ihr diese kurze Dankesnachricht zu Nyoma zurückbringen? Ihr könnt einen Hippogryphen zurück nach Dolanaar mieten. Besucht einfach unsere Hippogryphenmeisterin, Leora, wenn Ihr zum Abflug bereit seid. Sie wird Euch mit einem Rückflug nach Dolanaar helfen.", sourceObjective = "Bringt Schwester Aquinnes Notiz zu Leora, der Hippogryphenmeisterin in Darnassus.", progress = "Seid Ihr bereit, nach Dolanaar zurückzukehren?", completion = "Braucht Ihr einen Flug zurück nach Dolanaar?", sourceObjectiveStatus = "unverified-source-field" }
quests[6343] = { id = 6343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Nyoma", description = "Euch einen Flug zurück nach Dolanaar zu besorgen, wird einfach sein. Da Ihr Fidelio in Dolanaar bereits kennt, könnt Ihr ohne Probleme dorthin zurückfliegen.\n\nImmer wenn Ihr in einer neuen Stadt ankommt, solltet Ihr daran denken, mit dem Flugmeister zu sprechen, damit Ihr zu und von diesem neuen Ort fliegen könnt.\n\nSprecht mit mir, wenn Ihr bereit seid, einen Hippogryphen für den Rückflug nach Dolanaar zu mieten.", sourceObjective = "Sprecht mit Leora, um einen Hippogryphen zu mieten, der Euch nach Dolanaar zurückbringt. Sobald Ihr in Dolanaar angekommen seid, bringt Schwester Aquinnes Nachricht zu Nyoma.", progress = "{name}, Ihr seid aus Darnassus zurück?", completion = "Es klingt, als hätte es ihr sehr gefallen. Danke, dass Ihr das Buch zu Schwester Aquinne gebracht habt, {name}. Irgendwann bald werde ich ihre Einladung annehmen und sie in Darnassus besuchen.", sourceObjectiveStatus = "unverified-source-field" }
